with refreshed(number, steps) as (
values
  (1, '[{"title":"把句子讀明白","body":"先讀成兩個消息：「I met the man yesterday」（我昨天見過他）＋「The man is our new librarian」（他現在是新圖書館員）。昨天只影響 met，不會迫使 is 變成 was。"},{"title":"針對這句的錯法或疑問","body":"你可能想改 who → whom 或 is → was，其實兩個都不用改。who I met 的 who 是我遇見的人，普通英文可作受詞；whom 只是較正式。is 指這個人現在擔任圖書館員，不是昨天的動作。"},{"title":"看同一文法點的對照","body":"I met the man yesterday. ✓＋The man is our new librarian. ✓ 合成原句，met 仍是過去，is 仍是現在。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：met 發生在昨天，但 is 說的是現在職位。若寫成 was，有沒有額外證據說他現在不再是圖書館員？沒有。"}]'::jsonb),
  (2, '[{"title":"把句子讀明白","body":"先拆成「I bought the novel yesterday」＋「The novel is interesting」。novel 是已寫出的名詞；後面的 I bought 缺少買的對象。"},{"title":"針對這句的錯法或疑問","body":"為甚麼 what 錯？ 前面已有 novel，後面只能用 that／which 介紹它（也可省掉受詞關係字）。what 自己已是「所買的東西」，放在 novel 後等於重複當作另一個名詞，不是普通標準寫法。"},{"title":"看同一文法點的對照","body":"The novel that I bought is interesting. ✓；I kept what I bought. ✓（第二句前面沒有 novel 這個名詞。）"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：前面已經有 novel，還要再用 what 表「那件東西」嗎？不用；that／which／零受詞形式已足夠。"}]'::jsonb),
  (3, '[{"title":"把句子讀明白","body":"在圖書館工作的是「男孩的母親」，不是男孩。把 whose mother 讀成 the boy’s mother，再找 works 的主語就是 mother。"},{"title":"針對這句的錯法或疑問","body":"你可能想把 whose 改成 who’s，但 who’s 展開只會是 who is 或 who has；who is mother 不能解成「他的媽媽」。whose 才是「誰的」，而 mother 一個人，所以 works 加 -s。"},{"title":"看同一文法點的對照","body":"A boy whose mother works here ✓；A boy who’s waiting outside ✓。這兩個詞根本在做不同的事。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面的名詞是誰的？如果試用 who’s，展開成 who is／who has 還能讀通嗎？"}]'::jsonb),
  (4, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"in which 表示把筆記放在文件夾內，介詞與物件的關係正確。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The chair at that I sat was uncomfortable. → The chair at which I sat was uncomfortable.。因為前置 at 後用 which；也可把 at 放句尾。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (5, '[{"title":"把句子讀明白","body":"這句有幾個動詞？先分開找每個動詞自己的主語，不要把主句的人數或時間誤套進關係小句。"},{"title":"針對這句的錯法或疑問","body":"that 的動詞隨 books 複數用 are。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The books that is on the shelf are ours. → The books that are on the shelf are ours.。因為books 複數，that 子句用 are。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個動詞真正的主語是單數還是複數？時間又是在過去、現在或將來？"}]'::jsonb),
  (6, '[{"title":"把句子讀明白","body":"先還原意思：「坐在門旁邊的老師」＝ the teacher who is sitting by the door。不是「正在選址」的老師。"},{"title":"針對這句的錯法或疑問","body":"這題真正考 sit 的拼字：sit 加 -ing 要雙寫 t，變 sitting；siting 來自另一個字 site（選址），不是坐。主句 is our librarian 沒有錯。"},{"title":"看同一文法點的對照","body":"He is sitting on the chair. ✓；They are siting the new building near the park. ✓（這裏才是 site＝選址。）"},{"title":"下次遇到這種題怎樣自己判斷","body":"動詞原形如果是 sit，寫 -ing 時先試：sit → sitting（雙 t）。別被 siting 看起來像英文就放過它。"}]'::jsonb),
  (7, '[{"title":"把句子讀明白","body":"先找到 whose 後面的名詞：誰的子女／哪個物件的部分？再找它是單數還是複數。"},{"title":"針對這句的錯法或疑問","body":"who’s = who is 或 who has，不能表「某人的」。這句後面跟母親／單車／設計，所以必須寫 whose。試展開 who’s 就會知道原句讀不通。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：I met a boy whose mother works in the library.。whose 表示「屬於誰」，不是 who''s (= who is/has)。看它怎樣處理「who''s → whose」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面的名詞是誰的？如果試用 who’s，展開成 who is／who has 還能讀通嗎？"}]'::jsonb),
  (8, '[{"title":"把句子讀明白","body":"把每一組介紹讀清楚，先問「前面的這個名詞正在做甚麼／被人做了甚麼？」；不要把別人的動詞或主句的動詞算到它身上。"},{"title":"針對這句的錯法或疑問","body":"should 後用原形 read。 這一題只需把 reads 改為 read；不是把整句所有動詞一起換時態。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The song that I said you should hear is wonderful.。that 最後連到 hear 的受詞 song。看它怎樣處理「reads → read」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：兩個 who／that 是否分別指不同名詞？它們後面的動詞有沒有跟錯人或物？"}]'::jsonb),
  (9, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"that 代表接受寄送的信，was posted 是被動語態。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The parcel that sent yesterday has arrived. → The parcel that was sent yesterday has arrived.。因為parcel 是被寄送而不是自己寄送。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (10, '[{"title":"把句子讀明白","body":"The sun is a star 已是主要消息。「provides light」只是在已知的 the sun 後加一句「它會發光」。"},{"title":"針對這句的錯法或疑問","body":"這種插進主句中的補充，要用 , which provides light,。that 不可放在這一對逗號之間當補充關係字；不是因為 the sun 屬於哪一種物件。"},{"title":"看同一文法點的對照","body":"The sun, which provides light, is a star. ✓；The star that gives us light is the sun. ✓（後句的 that 用來分辨是哪顆星，沒有補充逗號。）"},{"title":"下次遇到這種題怎樣自己判斷","body":"把插入部分拿掉後剩下 The sun is a star。這證明它是額外補充，而不是非要靠它才知道是哪個太陽。"}]'::jsonb),
  (11, '[{"title":"把句子讀明白","body":"把 What I need 整組讀成「我需要的東西」，句子說的是「我需要的是一個短暫休息」。"},{"title":"針對這句的錯法或疑問","body":"不能因為前面有 What 就用 are。這裏 What I need 是一件需求，後面也有 a short break（單數），用 is 最自然。"},{"title":"看同一文法點的對照","body":"What I need is a break. ✓；The things I need are on the table. ✓（後句主語 things 才是複數。）"},{"title":"下次遇到這種題怎樣自己判斷","body":"先問：主語是在指一件需求還是一組東西？若只是一件事，別把 What 誤當成複數。"}]'::jsonb),
  (12, '[{"title":"把句子讀明白","body":"先找到 whose 後面的名詞：誰的子女／哪個物件的部分？再找它是單數還是複數。"},{"title":"針對這句的錯法或疑問","body":"whose book 是 I read 的受詞，並非作家讀我的書。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The author whose novel I read it visited our school. → The author whose novel I read visited our school.。因為whose novel 已是 read 的受詞，不再重複 it。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面的名詞是誰的？如果試用 who’s，展開成 who is／who has 還能讀通嗎？"}]'::jsonb),
  (13, '[{"title":"把句子讀明白","body":"這題專門提醒你不要把已經正確的日常寫法當錯誤；要先看真正的句意，而不是只背一條「更正式」的偏好。"},{"title":"針對這句的錯法或疑問","body":"that 連接 book 和 I bought；不同語法書可能給 that 不同名稱。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The book that I bought is new. ✓。你可以先把句中介紹的部分拿走，再放回來；that 連接 book 和 I bought；不同語法書可能給 that 不同名稱。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是文法真的不成立，還是只是比較少見／比較正式？只有真正錯誤才打 ✗。"}]'::jsonb),
  (14, '[{"title":"把句子讀明白","body":"逗號之前先說完「Nora」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"補充句中受詞 who 也正確，whom 是較正式替代。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：Nora, who I called yesterday, is on her way. ✓。你可以先把句中介紹的部分拿走，再放回來；補充句中受詞 who 也正確，whom 是較正式替代。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (15, '[{"title":"把句子讀明白","body":"找 to 後面的動詞和真正做事的人：是 first runner 自己 arrive，還是有人要 sign forms？"},{"title":"針對這句的錯法或疑問","body":"原句的 children read 在此處不合用；for + 人 + to + 動詞原形。 正確修改是 children read → children to read，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：Here is a leaflet for the parents to read.。for the parents 指明誰會閱讀傳單。看它怎樣處理「children read → children to read」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：to 後動詞是否原形？要講 sit on a chair 時，那個 on 有沒有跟着保留？"}]'::jsonb),
  (16, '[{"title":"把句子讀明白","body":"看看 It was ... who/that 是在強調「正是誰」，還是 the news/fact that ... 在說「消息是甚麼」。"},{"title":"針對這句的錯法或疑問","body":"where she keeps ... 是 know 的間接問題內容，沒有前面名詞。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：I do not know where does she keep the folder. → I do not know where she keeps the folder.。因為間接問句的詞序用 she keeps。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是在強調某個人，還是在說明 the news／the fact 的內容？兩種 that 的工作不同。"}]'::jsonb),
  (17, '[{"title":"把句子讀明白","body":"找 to 後面的動詞和真正做事的人：是 first runner 自己 arrive，還是有人要 sign forms？"},{"title":"針對這句的錯法或疑問","body":"for the parents 指明誰會閱讀傳單。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：Here is a book for the children read. → Here is a book for the children to read.。因為for + 人 + to + 動詞原形。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：to 後動詞是否原形？要講 sit on a chair 時，那個 on 有沒有跟着保留？"}]'::jsonb),
  (18, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"句中原來的 met her 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；that 已代表被見到的 pupil，不再加 her。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：We found the notebook that Amelia had misplaced.。notebook 是 found 的受詞，也由 that Amelia had misplaced 再加描述。看它怎樣處理「met her → met」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (19, '[{"title":"把句子讀明白","body":"這句有幾個動詞？先分開找每個動詞自己的主語，不要把主句的人數或時間誤套進關係小句。"},{"title":"針對這句的錯法或疑問","body":"找出 is 自己對應哪個主語。books 複數，that 子句用 are。 are 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The books that are on the shelf belong to our class.。that 的動詞隨 books 複數用 are。看它怎樣處理「is → are」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個動詞真正的主語是單數還是複數？時間又是在過去、現在或將來？"}]'::jsonb),
  (20, '[{"title":"把句子讀明白","body":"把每一組介紹讀清楚，先問「前面的這個名詞正在做甚麼／被人做了甚麼？」；不要把別人的動詞或主句的動詞算到它身上。"},{"title":"針對這句的錯法或疑問","body":"兩個 that 子句都介紹 books，分別提出兩個條件。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The reports that I read and that I checked them are here. → The reports that I read and that I checked are here.。因為第二組 that 已代表 reports 作 checked 的受詞，不再加 them。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：兩個 who／that 是否分別指不同名詞？它們後面的動詞有沒有跟錯人或物？"}]'::jsonb),
  (21, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"who 是 can repair 的主語，can 後用動詞原形。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The woman who can repair the projector will visit tomorrow. ✓。你可以先把句中介紹的部分拿走，再放回來；who 是 can repair 的主語，can 後用動詞原形。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (22, '[{"title":"把句子讀明白","body":"這句有幾個動詞？先分開找每個動詞自己的主語，不要把主句的人數或時間誤套進關係小句。"},{"title":"針對這句的錯法或疑問","body":"找出 have 自己對應哪個主語。woman 單數，完成式用 has。 has 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The pupil who has finished the report can leave.。has finished 強調到現在已完成。看它怎樣處理「have → has」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個動詞真正的主語是單數還是複數？時間又是在過去、現在或將來？"}]'::jsonb),
  (23, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"主句的 is smiling 不可因中間有 who won 就漏掉。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The students who arrived early they received free tickets. → The students who arrived early received free tickets.。因為完整主句已有 The students 作主語，不要重複 they。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (24, '[{"title":"把句子讀明白","body":"先把句子讀成「我只想要一間安靜房間」。前面已經有 All，表示我想要的全部。"},{"title":"針對這句的錯法或疑問","body":"what 自己就可表示「我想要的東西」，所以 What I want is... 可以；但前面若已有 All，普通寫法是 All that I want... 或 All I want...，不能兩種句型拼成 All what。"},{"title":"看同一文法點的對照","body":"All that I want is a quiet room. ✓；All I want is a quiet room. ✓；What I want is a quiet room. ✓；All what I want... ✗。"},{"title":"下次遇到這種題怎樣自己判斷","body":"看到 All 和 What 擠在一起，先試分別寫成 All (that) I want 和 What I want，選其中一種完整句型。"}]'::jsonb),
  (25, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"主問句用 Do，關係子句 who lives 仍用一般陳述次序。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：Do you know the woman who does she live here? → Do you know the woman who lives here?。因為外面是問句，關係子句不用疑問倒裝。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (26, '[{"title":"把句子讀明白","body":"看看 It was ... who/that 是在強調「正是誰」，還是 the news/fact that ... 在說「消息是甚麼」。"},{"title":"針對這句的錯法或疑問","body":"than 引出比較，不必把它誤當普通關係代字。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：Mia is taller than her brother is. ✓。你可以先把句中介紹的部分拿走，再放回來；than 引出比較，不必把它誤當普通關係代字。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是在強調某個人，還是在說明 the news／the fact 的內容？兩種 that 的工作不同。"}]'::jsonb),
  (27, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"which 指 printer；這部打印機是 broke 的主語。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The bicycle who was left by the gate belongs to Alex. → The bicycle which was left by the gate belongs to Alex.。因為普通物件 bicycle 用 which 或 that。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (28, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"句中原來的 watched it 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；省掉 that 也不等於要補 it。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The camera I borrowed yesterday is broken.。雖省去關係字，borrowed 後面仍不可重複 it。看它怎樣處理「watched it → watched」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (29, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"we 是 bought 的主語，which 代表被買的電腦。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The laptop which we bought at the fair is fast. ✓。你可以先把句中介紹的部分拿走，再放回來；we 是 bought 的主語，which 代表被買的電腦。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (30, '[{"title":"把句子讀明白","body":"看看 It was ... who/that 是在強調「正是誰」，還是 the news/fact that ... 在說「消息是甚麼」。"},{"title":"針對這句的錯法或疑問","body":"What I need 整組作焦點，後面 is 給答案。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：What I need are a short break. → What I need is a short break.。因為what 子句當一個需求，這裏用 is。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是在強調某個人，還是在說明 the news／the fact 的內容？兩種 that 的工作不同。"}]'::jsonb),
  (31, '[{"title":"把句子讀明白","body":"逗號之前先說完「The sun」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"已明確的天體仍可加補充關係子句。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The sun, that provides light, is a star. → The sun, which provides light, is a star.。因為已知天體的補充說明，用 which。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (32, '[{"title":"把句子讀明白","body":"逗號之前先說完「We met Jack」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"為甚麼那個 that 不能留？ 逗號前已交代清楚對象／整件事，逗號後只是在補充。標準英文不在這類補充關係子句用 that。如果後面是在評論整件事，要用 which；如果只是接着介紹一位已知的人，用 who。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：He emailed Nora, who replied a week later.。後續的 who 子句可以發生在一星期之後。看它怎樣處理「that → who」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面是在評論剛剛發生的整件事，還是找哪一個人／物？前者常用逗號 which，不可直接換成 that。"}]'::jsonb),
  (33, '[{"title":"把句子讀明白","body":"把短描述還原成 who is doing／which was made／which is being repaired 讀一次，看看誰做、誰被做、動作是否正在發生。"},{"title":"針對這句的錯法或疑問","body":"找出 is 自己對應哪個主語。chairs 複數主語，所以用 are。 are 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The seats available today are near the window.。available today 是名詞後置的形容詞片語。看它怎樣處理「is → are」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (34, '[{"title":"把句子讀明白","body":"把每一組介紹讀清楚，先問「前面的這個名詞正在做甚麼／被人做了甚麼？」；不要把別人的動詞或主句的動詞算到它身上。"},{"title":"針對這句的錯法或疑問","body":"句中原來的 checked them 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；第二組 that 已代表 reports 作 checked 的受詞，不再加 them。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The books that I borrowed and that I finished are on this shelf.。兩個 that 子句都介紹 books，分別提出兩個條件。看它怎樣處理「checked them → checked」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：兩個 who／that 是否分別指不同名詞？它們後面的動詞有沒有跟錯人或物？"}]'::jsonb),
  (35, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"找出 needs 自己對應哪個主語。you 作主語，動詞用 need。 need 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：Bring whatever tools you need for the repair.。whatever tools 是一組，限定物件類別。看它怎樣處理「needs → need」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (36, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"how the engineer fixed 是 know 的內容，沒有前面的 way。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：I know how the engineer fixed the door. ✓。你可以先把句中介紹的部分拿走，再放回來；how the engineer fixed 是 know 的內容，沒有前面的 way。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (37, '[{"title":"把句子讀明白","body":"The folder 是整個文件夾；its contents 是裏面多項文件／內容。這句其實有兩個主語。"},{"title":"針對這句的錯法或疑問","body":"在逗號內，contents 是複數，所以要說 whose contents are private；逗號外 The folder 單數，所以仍是 is locked。只改第一個 is，不可把兩個 is 一起改 are。"},{"title":"看同一文法點的對照","body":"The contents are private. ✓＋The folder is locked. ✓。合成：The folder, whose contents are private, is locked."},{"title":"下次遇到這種題怎樣自己判斷","body":"把每個動詞都畫箭嘴連回自己的主語：contents → are；folder → is。"}]'::jsonb),
  (38, '[{"title":"把句子讀明白","body":"先找到 whose 後面的名詞：誰的子女／哪個物件的部分？再找它是單數還是複數。"},{"title":"針對這句的錯法或疑問","body":"whose bicycle 表示女孩的單車被偷，不是女孩被偷。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The girl whose bicycle was stolen is upset. ✓。你可以先把句中介紹的部分拿走，再放回來；whose bicycle 表示女孩的單車被偷，不是女孩被偷。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面的名詞是誰的？如果試用 who’s，展開成 who is／who has 還能讀通嗎？"}]'::jsonb),
  (39, '[{"title":"把句子讀明白","body":"這句有幾個動詞？先分開找每個動詞自己的主語，不要把主句的人數或時間誤套進關係小句。"},{"title":"針對這句的錯法或疑問","body":"All who ... 可以指符合條件的全體申請人。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：All who applies will receive a reply. → All who apply will receive a reply.。因為all who 指多人，全組用 apply。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個動詞真正的主語是單數還是複數？時間又是在過去、現在或將來？"}]'::jsonb),
  (40, '[{"title":"把句子讀明白","body":"逗號之前先說完「My computer」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"為甚麼那個 that 不能留？ 逗號前已交代清楚對象／整件事，逗號後只是在補充。標準英文不在這類補充關係子句用 that。如果後面是在評論整件事，要用 which；如果只是接着介紹一位已知的人，用 who。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：My tablet, which is five years old, still works.。補充關係子句有逗號，要用 which 而非 that。看它怎樣處理「that → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (41, '[{"title":"把句子讀明白","body":"找 to 後面的動詞和真正做事的人：是 first runner 自己 arrive，還是有人要 sign forms？"},{"title":"針對這句的錯法或疑問","body":"only 加 to finish 表示唯一完成者。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：He was the only runner to finished the race. → He was the only runner to finish the race.。因為only runner to + 原形。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：to 後動詞是否原形？要講 sit on a chair 時，那個 on 有沒有跟着保留？"}]'::jsonb),
  (42, '[{"title":"把句子讀明白","body":"She is one of the workers 是「她是眾多工人之一」。who 後面介紹的是 workers 這一群（夜班工人）。"},{"title":"針對這句的錯法或疑問","body":"不是因為整句一開始有 She，就把 who 後改成 works。在普通這種寫法中，who 指複數 workers，所以 who work at night。"},{"title":"看同一文法點的對照","body":"She is one of the workers who work at night. ✓；She is the only one of the workers who works at night. ✓（only one 把焦點放回唯一的人）。"},{"title":"下次遇到這種題怎樣自己判斷","body":"先把 who 畫箭嘴連回 workers，問 who 在介紹「她一個」還是「這組工人」。"}]'::jsonb),
  (43, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"two of which 指四隻杯中的兩隻，補充句用 which。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：She bought five paintings, two of that were damaged. → She bought five paintings, two of which were damaged.。因為部分數量 two of which 指前面的一組物件。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (44, '[{"title":"把句子讀明白","body":"把句子只看成「Give the medal to [the person who wins]」。wins 的主語是贏的人，所以要選 whoever，不因前面有 to 就強迫用 whomever。"},{"title":"針對這句的錯法或疑問","body":"注意 whoever 在 wins 裏是主語，所以「to whoever wins」成立。to 後面接的是 whoever wins 整組，而不是一個單獨作受詞的 whoever。相反，Invite whomever you trust 的 trust 主語是 you。"},{"title":"看同一文法點的對照","body":"Give it to whoever wins. ✓；Invite whomever you trust. ✓，因為 trust 的主語變成 you。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：wins 是誰做？是 whoever；to 後接的是整組 whoever wins，不要只看 to。"}]'::jsonb),
  (45, '[{"title":"把句子讀明白","body":"逗號之前先說完「We met Ella」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"who later... 是後續消息，不是辨認哪一位 Ella。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：We met Ella, who later became our coach. ✓。你可以先把句中介紹的部分拿走，再放回來；who later... 是後續消息，不是辨認哪一位 Ella。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面是在評論剛剛發生的整件事，還是找哪一個人／物？前者常用逗號 which，不可直接換成 that。"}]'::jsonb),
  (46, '[{"title":"把句子讀明白","body":"逗號前 The team won the match 已是整件事。後面意思是「球隊贏了，這件事令教練高興」。"},{"title":"針對這句的錯法或疑問","body":"這種補充結果要用 which delighted the coach。that 不能在這個逗號後回指整件贏球的事情；that 若放在名詞後而沒有逗號，可以說 the match that we won（我們贏的那場比賽）。"},{"title":"看同一文法點的對照","body":"The team won, which delighted the coach. ✓；The match that we won was exciting. ✓。第二句的 that 是指出哪場比賽，不是說整件事的結果。"},{"title":"下次遇到這種題怎樣自己判斷","body":"可以先把 which 換成「這件事」來讀；若讀得通，就別改成逗號後的 that。"}]'::jsonb),
  (47, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"前置 about 後面是 which，不直接接 that。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The issue about that we argued was serious. → The issue about which we argued was serious.。因為前置 about 後不能直接用 that。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (48, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"the way 後可直接接解釋方法的子句。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：This is the way how we solved the puzzle. → This is the way that we solved the puzzle.。因為the way that ... 或 the way ...，不機械疊加 how。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (49, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"句中原來的 I think he 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；需要 who 連回 player，who 作 scored 的主語。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The student who I think knows the answer raised a hand.。在 knows the answer 一層，student 是主語，因此 who 正確。看它怎樣處理「I think he → who I think」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (50, '[{"title":"把句子讀明白","body":"找 to 後面的動詞和真正做事的人：是 first runner 自己 arrive，還是有人要 sign forms？"},{"title":"針對這句的錯法或疑問","body":"原句的 finished 在此處不合用；only runner to + 原形。 正確修改是 finished → finish，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：He was the only runner to finish the course.。only 加 to finish 表示唯一完成者。看它怎樣處理「finished → finish」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：to 後動詞是否原形？要講 sit on a chair 時，那個 on 有沒有跟着保留？"}]'::jsonb),
  (51, '[{"title":"把句子讀明白","body":"逗號之前先說完「The match was cancelled」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"為甚麼那個 that 不能留？ 逗號前已交代清楚對象／整件事，逗號後只是在補充。標準英文不在這類補充關係子句用 that。如果後面是在評論整件事，要用 which；如果只是接着介紹一位已知的人，用 who。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The road was closed, which made the pupils late.。which 可以把前面事件與造成的結果連起來。看它怎樣處理「that → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面是在評論剛剛發生的整件事，還是找哪一個人／物？前者常用逗號 which，不可直接換成 that。"}]'::jsonb),
  (52, '[{"title":"把句子讀明白","body":"逗號之前先說完「The players」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"原句的 tired went 在此處不合用；補充子句結尾要加逗號，讓主句繼續。 正確修改是 tired went → tired, went，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：My older sister, who studies in Bristol, is visiting.。句中補充子句有前後兩個逗號。看它怎樣處理「tired went → tired, went」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (53, '[{"title":"把句子讀明白","body":"先問後面的字是在幫忙指出「哪一個人／哪一件事」，還是在補充已知道的人／物；這會影響逗號及能否用 that。"},{"title":"針對這句的錯法或疑問","body":"first 加 who 子句說明抵達先後。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The first player who crossed the line they won. → The first player who crossed the line won.。因為The first player ... 已是主句主語，不重複 they。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (54, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"原句的 video was 在此處不合用；主語關係字不能單靠空白直接省略。 正確修改是 video was → video that was，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The dog that barked loudly frightened the visitors.。that 是 barked 的主語，標準書面語須保留。看它怎樣處理「video was → video that was」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (55, '[{"title":"把句子讀明白","body":"先問後面的字是在幫忙指出「哪一個人／哪一件事」，還是在補充已知道的人／物；這會影響逗號及能否用 that。"},{"title":"針對這句的錯法或疑問","body":"句中原來的 they won 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；The first player ... 已是主句主語，不重複 they。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The first runner who arrived received a medal.。first 加 who 子句說明抵達先後。看它怎樣處理「they won → won」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (56, '[{"title":"把句子讀明白","body":"逗號之前先說完「The players」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"逗號表示所談球員都累了，不只某一部分。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The players, who were exhausted, went home together. ✓。你可以先把句中介紹的部分拿走，再放回來；逗號表示所談球員都累了，不只某一部分。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (57, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"句中原來的 met she 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；that 已是 met 的受詞，she 不能在主句與 teaches 間胡亂插入。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The camera I borrowed yesterday is broken.。雖省去關係字，borrowed 後面仍不可重複 it。看它怎樣處理「met she → met」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (58, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"零受詞關係字後，about 仍要保留。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：This is the subject I talked yesterday. → This is the subject I talked about yesterday.。因為談論某個題目用 talk about。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (59, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"不知道買的是甚麼，是間接問句的內容。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：I don''t know what did he buy yesterday. → I don''t know what he bought yesterday.。因為間接問句用主語在動詞前的陳述次序。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (60, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"three of whom 指十位客人中的三位。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：Six musicians attended, three of which played later. → Six musicians attended, three of whom played later.。因為音樂家是人，數量部分後用 whom。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (61, '[{"title":"把句子讀明白","body":"看看 It was ... who/that 是在強調「正是誰」，還是 the news/fact that ... 在說「消息是甚麼」。"},{"title":"針對這句的錯法或疑問","body":"whereby 是較正式的「透過該安排」表達。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：They designed a plan whereby everyone could help. ✓。你可以先把句中介紹的部分拿走，再放回來；whereby 是較正式的「透過該安排」表達。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是在強調某個人，還是在說明 the news／the fact 的內容？兩種 that 的工作不同。"}]'::jsonb),
  (62, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"原句的 talked 在此處不合用；談論某個題目用 talk about。 正確修改是 talked → talked about，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：This is the topic I was talking about.。零受詞關係字後，about 仍要保留。看它怎樣處理「talked → talked about」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (63, '[{"title":"把句子讀明白","body":"看看 It was ... who/that 是在強調「正是誰」，還是 the news/fact that ... 在說「消息是甚麼」。"},{"title":"針對這句的錯法或疑問","body":"句中原來的 did she buy 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；間接問句不倒裝，過去用 bought。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：I do not know which dress she bought.。which dress 引出不知道哪件，不是介紹外面的 dress。看它怎樣處理「did she buy → she bought」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是在強調某個人，還是在說明 the news／the fact 的內容？兩種 that 的工作不同。"}]'::jsonb),
  (64, '[{"title":"把句子讀明白","body":"先問後面的字是在幫忙指出「哪一個人／哪一件事」，還是在補充已知道的人／物；這會影響逗號及能否用 that。"},{"title":"針對這句的錯法或疑問","body":"補充子句連受詞 whom 亦不能直接省掉。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：Maya, I met at the concert, will visit us. → Maya, whom I met at the concert, will visit us.。因為補充子句即使是受詞也不能省關係字。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (65, '[{"title":"把句子讀明白","body":"逗號之前先說完「He emailed Ms Lee」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"which 可指逗號前整件事：例如「比賽取消」導致球員失望；不是只說某個叫 match 的東西。這類逗號後評論／結果不能直接換成 that。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：He emailed Nora, who replied a week later.。後續的 who 子句可以發生在一星期之後。看它怎樣處理「which → who」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面是在評論剛剛發生的整件事，還是找哪一個人／物？前者常用逗號 which，不可直接換成 that。"}]'::jsonb),
  (66, '[{"title":"把句子讀明白","body":"先找到 whose 後面的名詞：誰的子女／哪個物件的部分？再找它是單數還是複數。"},{"title":"針對這句的錯法或疑問","body":"找出 wins 自己對應哪個主語。whose designs 是複數，動詞用 win。 win 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The girl whose parents work here is cheerful.。parents 是複數，關係子句用 work。看它怎樣處理「wins → win」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面的名詞是誰的？如果試用 who’s，展開成 who is／who has 還能讀通嗎？"}]'::jsonb),
  (67, '[{"title":"把句子讀明白","body":"逗號之前先說完「He emailed Nora」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"後續的 who 子句可以發生在一星期之後。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：We met Jack, that later became our captain. → We met Jack, who later became our captain.。因為接續人物後來發展的補充句用 who。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面是在評論剛剛發生的整件事，還是找哪一個人／物？前者常用逗號 which，不可直接換成 that。"}]'::jsonb),
  (68, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"原句的 remains 在此處不合用；you 作主語，動詞原形；Whatever happens 本身正確。 正確修改是 remains → remain，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：Whatever happens, remain calm.。句首 Whatever happens 是「無論發生甚麼」的讓步子句。看它怎樣處理「remains → remain」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (69, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"drawings 是外面的名詞；與 I kept what my sister made 不同。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：I kept the drawings my sister made. ✓。你可以先把句中介紹的部分拿走，再放回來；drawings 是外面的名詞；與 I kept what my sister made 不同。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (70, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"what ... cooked 整組表示她煮的東西。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：I ate what my grandmother cooked for us. ✓。你可以先把句中介紹的部分拿走，再放回來；what ... cooked 整組表示她煮的東西。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (71, '[{"title":"把句子讀明白","body":"找 to 後面的動詞和真正做事的人：是 first runner 自己 arrive，還是有人要 sign forms？"},{"title":"針對這句的錯法或疑問","body":"not to be ignored 保留「不可忽略」的否定。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：These instructions not be ignored are important. → These instructions not to be ignored are important.。因為否定的待處理用途寫 not to be ignored。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：to 後動詞是否原形？要講 sit on a chair 時，那個 on 有沒有跟着保留？"}]'::jsonb),
  (72, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"to 後接整組 whoever wins，whoever 是 wins 的主語。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：Give the medal to whomever wins. → Give the medal to whoever wins.。因為wins 的主語是 whoever，即使整組在 to 後。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (73, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"句中原來的 on it 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；that 指 seat，介詞 on 仍保留，但不再加 it。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The chair that I sat on needs repairing.。sit on a chair 與 sit in a room 所用介詞不同。看它怎樣處理「on it → on」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (74, '[{"title":"把句子讀明白","body":"把每一組介紹讀清楚，先問「前面的這個名詞正在做甚麼／被人做了甚麼？」；不要把別人的動詞或主句的動詞算到它身上。"},{"title":"針對這句的錯法或疑問","body":"who 後的 sang 和 danced 是同一女孩兩個動作。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The girl who sings and who dance won. → The girl who sings and who dances won.。因為第二個 who 仍指 girl，所以 dances。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：兩個 who／that 是否分別指不同名詞？它們後面的動詞有沒有跟錯人或物？"}]'::jsonb),
  (75, '[{"title":"把句子讀明白","body":"只讀「Take whatever you need」（拿你需要的任何東西）。whatever 已包含「任何東西」；that 沒有另一個需要接回去的名詞。"},{"title":"針對這句的錯法或疑問","body":"whatever 本身已包住「任何……的東西」。後面直接接 you need，不再加 that。若先寫 the things，才可用 the things that you need。"},{"title":"看同一文法點的對照","body":"Take whatever you need. ✓；Take the things that you need. ✓。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (76, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"wherever 表不限制坐在哪裏。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：Sit wherever do you feel comfortable. → Sit wherever you feel comfortable.。因為wherever 子句不用疑問倒裝。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (77, '[{"title":"把句子讀明白","body":"看看 It was ... who/that 是在強調「正是誰」，還是 the news/fact that ... 在說「消息是甚麼」。"},{"title":"針對這句的錯法或疑問","body":"句中原來的 does she keep 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；間接問句的詞序用 she keeps。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：I know where she keeps her notes.。where she keeps ... 是 know 的間接問題內容，沒有前面名詞。看它怎樣處理「does she keep → she keeps」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是在強調某個人，還是在說明 the news／the fact 的內容？兩種 that 的工作不同。"}]'::jsonb),
  (78, '[{"title":"把句子讀明白","body":"主句是 The picture looks lovely（那幅畫很好看）；插入的 I bought yesterday 是補充「我昨天買了它」。"},{"title":"針對這句的錯法或疑問","body":"因為這段夾在兩個逗號中間，是額外補充的關係句。就算 picture 是 bought 的受詞，也不能像沒有逗號的限定句般直接省 which。"},{"title":"看同一文法點的對照","body":"The picture, which I bought yesterday, looks lovely. ✓；The picture I bought yesterday looks lovely. ✓（後一句改成沒有逗號、用來指出哪一幅畫。）"},{"title":"下次遇到這種題怎樣自己判斷","body":"先把逗號內部分遮住：The picture looks lovely；再把 which I bought yesterday 插回，兩邊逗號要保留。"}]'::jsonb),
  (79, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"who 同時代表 artist 與 painted 的主語。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The artist who painted that mural lives nearby. ✓。你可以先把句中介紹的部分拿走，再放回來；who 同時代表 artist 與 painted 的主語。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (80, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"雖省去關係字，borrowed 後面仍不可重複 it。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The documentary we watched it was interesting. → The documentary we watched was interesting.。因為省掉 that 也不等於要補 it。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (81, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"who 已是 helped 的主語，毋須另寫 she。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The boy who he lives near the harbour plays chess. → The boy who lives near the harbour plays chess.。因為who 已代表 boy 並作 lives 的主語。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (82, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"who 代表 wait for 的對象；介詞 for 要保留。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The woman I waited has just arrived. → The woman I waited for has just arrived.。因為wait for 的 for 不可漏。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (83, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"原句的 spoke 在此處不合用；speak to someone 的 to 不可省。 正確修改是 spoke → spoke to，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The person I spoke to was friendly.。介詞 to 留在關係子句後面是標準英文。看它怎樣處理「spoke → spoke to」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (84, '[{"title":"把句子讀明白","body":"把短描述還原成 who is doing／which was made／which is being repaired 讀一次，看看誰做、誰被做、動作是否正在發生。"},{"title":"針對這句的錯法或疑問","body":"逗號夾出的分詞片語可補充人物狀態。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：Mia, smiling happily, waved to her friends. ✓。你可以先把句中介紹的部分拿走，再放回來；逗號夾出的分詞片語可補充人物狀態。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (85, '[{"title":"把句子讀明白","body":"把每一組介紹讀清楚，先問「前面的這個名詞正在做甚麼／被人做了甚麼？」；不要把別人的動詞或主句的動詞算到它身上。"},{"title":"針對這句的錯法或疑問","body":"who 是 is honest 的主語，I think 插在中間。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The boy whom I think is honest helped us. → The boy who I think is honest helped us.。因為在 is honest 中 boy 是主語，用 who。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：兩個 who／that 是否分別指不同名詞？它們後面的動詞有沒有跟錯人或物？"}]'::jsonb),
  (86, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"who 指護士，而護士就是 checked 的人。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The girl which organised the bake sale is in Class 2B. → The girl who organised the bake sale is in Class 2B.。因為這裏介紹人，限定人物通常用 who 或 that。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (87, '[{"title":"把句子讀明白","body":"The man who lives next door 是「住在隔壁的男子」。他本人在 lives 裏做主語，who 已指向 man。"},{"title":"針對這句的錯法或疑問","body":"不要因為 who 沒有中文直接對應字就刪掉。who lives 的 who 是後面動作的主語；刪了會變成「The man lives next door is friendly」，夾着兩個完整動詞而沒有連接。"},{"title":"看同一文法點的對照","body":"The man who lives next door is friendly. ✓；The man I met next door is friendly. ✓（第二句有 I 做 met 的主語，所以可省受詞 who）。"},{"title":"下次遇到這種題怎樣自己判斷","body":"問「who 後面有沒有另外一個主語？」本句沒有，因為 who 本身就是那位住在隔壁的人。"}]'::jsonb),
  (88, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"前置 in 後面接 whose house 整個名詞片語。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The friend in whose we stayed was kind. → The friend in whose house we stayed was kind.。因為in whose 後需要所屬名詞如 house。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (89, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"介詞 to 留在關係子句後面是標準英文。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The friend I spoke yesterday has a new job. → The friend I spoke to yesterday has a new job.。因為speak to someone 的 to 不可省。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (90, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"whom 通常不是做事的主語。這裏是「那個人安排／唱歌／知道答案」，即 who arranged／who sings／who is ...；I think 只是中間的說話者看法，不會把 who 變成受詞。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The woman who I think is responsible has arrived.。在 is responsible 裏，woman 是主語；I think 只是插入語。看它怎樣處理「whom → who」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (91, '[{"title":"把句子讀明白","body":"把短描述還原成 who is doing／which was made／which is being repaired 讀一次，看看誰做、誰被做、動作是否正在發生。"},{"title":"針對這句的錯法或疑問","body":"standing beside ... 可作名詞後的短修飾語。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The man standing beside the gate is our caretaker. ✓。你可以先把句中介紹的部分拿走，再放回來；standing beside ... 可作名詞後的短修飾語。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (92, '[{"title":"把句子讀明白","body":"把每一組介紹讀清楚，先問「前面的這個名詞正在做甚麼／被人做了甚麼？」；不要把別人的動詞或主句的動詞算到它身上。"},{"title":"針對這句的錯法或疑問","body":"whom 通常不是做事的主語。這裏是「那個人安排／唱歌／知道答案」，即 who arranged／who sings／who is ...；I think 只是中間的說話者看法，不會把 who 變成受詞。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The boy who I think is honest helped us.。who 是 is honest 的主語，I think 插在中間。看它怎樣處理「whom → who」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：兩個 who／that 是否分別指不同名詞？它們後面的動詞有沒有跟錯人或物？"}]'::jsonb),
  (93, '[{"title":"把句子讀明白","body":"這題專門提醒你不要把已經正確的日常寫法當錯誤；要先看真正的句意，而不是只背一條「更正式」的偏好。"},{"title":"針對這句的錯法或疑問","body":"句中原來的 who she 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；who 已是 lives 的主語，不重複 she。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The man who lives next door is friendly.。正式書面句 who 已作主語，不重複 he。看它怎樣處理「who she → who」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是文法真的不成立，還是只是比較少見／比較正式？只有真正錯誤才打 ✗。"}]'::jsonb),
  (94, '[{"title":"把句子讀明白","body":"逗號之前先說完「Our two monitors」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"找出 helps 自己對應哪個主語。who 代兩位 monitors，複數動詞 help。 help 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：My older sister, who studies in Bristol, is visiting.。句中補充子句有前後兩個逗號。看它怎樣處理「helps → help」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (95, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"為甚麼這裏要 whom？ 介詞（to／for／with）已放在關係字前面；在標準正式用法中，人物要寫 to whom／for whom／with whom。但 the person who I spoke to 也正確，因為介詞放在句尾，結構不同。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The tutor to whom I sent the email replied promptly.。to 是前置介詞，指人時正式寫 whom。看它怎樣處理「who → whom」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (96, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"句中原來的 that he 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；that 已是 helped 的主語，不再重複 he。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：I met a volunteer who repairs bicycles after school.。who 取代原本第二句的 she/he，合句時不再重複主語。看它怎樣處理「that he → that」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (97, '[{"title":"把句子讀明白","body":"這句有幾個動詞？先分開找每個動詞自己的主語，不要把主句的人數或時間誤套進關係小句。"},{"title":"針對這句的錯法或疑問","body":"沒逗號時可選出住附近的一部分朋友。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：My friends who live nearby visited me. ✓。你可以先把句中介紹的部分拿走，再放回來；沒逗號時可選出住附近的一部分朋友。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個動詞真正的主語是單數還是複數？時間又是在過去、現在或將來？"}]'::jsonb),
  (98, '[{"title":"把句子讀明白","body":"這句有幾個動詞？先分開找每個動詞自己的主語，不要把主句的人數或時間誤套進關係小句。"},{"title":"針對這句的錯法或疑問","body":"boys 是複數，關係子句用 live 而不是 lives。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The girls who lives upstairs are friendly. → The girls who live upstairs are friendly.。因為girls 複數，who 子句用 live。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個動詞真正的主語是單數還是複數？時間又是在過去、現在或將來？"}]'::jsonb),
  (99, '[{"title":"把句子讀明白","body":"這句有幾個動詞？先分開找每個動詞自己的主語，不要把主句的人數或時間誤套進關係小句。"},{"title":"針對這句的錯法或疑問","body":"找出 lives 自己對應哪個主語。neighbours 複數，who 子句用 live。 live 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The boys who live upstairs are friendly.。boys 是複數，關係子句用 live 而不是 lives。看它怎樣處理「lives → live」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個動詞真正的主語是單數還是複數？時間又是在過去、現在或將來？"}]'::jsonb),
  (100, '[{"title":"把句子讀明白","body":"先找到 whose 後面的名詞：誰的子女／哪個物件的部分？再找它是單數還是複數。"},{"title":"針對這句的錯法或疑問","body":"找出 works 自己對應哪個主語。parents 是複數，關係子句動詞用 work。 work 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The girl whose parents work here is cheerful.。parents 是複數，關係子句用 work。看它怎樣處理「works → work」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面的名詞是誰的？如果試用 who’s，展開成 who is／who has 還能讀通嗎？"}]'::jsonb),
  (101, '[{"title":"把句子讀明白","body":"這句的意思是「請邀請你信任的任何人」。動作 trust 的人是 you，不是 whoever。"},{"title":"針對這句的錯法或疑問","body":"you trust 是標準一般現在式：you 後面用 trust，不加 -s。trusts 應跟 he／she 這類一個人的主語。即使 whoever 是單數概念，也不會令旁邊 you 的動詞加 -s。"},{"title":"看同一文法點的對照","body":"Invite whoever you trust. ✓；Invite someone who trusts you. ✓（第二句做信任動作的人變成 someone，才用 trusts。）"},{"title":"下次遇到這種題怎樣自己判斷","body":"找動詞 trust 真正的主語；圈出 you，再決定是否加 -s。"}]'::jsonb),
  (102, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"這裏的 point 是抽象的「階段／情況」，不是幾點鐘；用 where 表「到了那種情況」，例如 a point where we had to decide。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：We reached a point where we had to make a choice.。point 是抽象階段，不是真正地圖地點。看它怎樣處理「when → where」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (103, '[{"title":"把句子讀明白","body":"先問後面的字是在幫忙指出「哪一個人／哪一件事」，還是在補充已知道的人／物；這會影響逗號及能否用 that。"},{"title":"針對這句的錯法或疑問","body":"who sleep well 泛指一類人，並非只挑選兩個人之一。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：People who sleep well often concentrate better. ✓。你可以先把句中介紹的部分拿走，再放回來；who sleep well 泛指一類人，並非只挑選兩個人之一。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (104, '[{"title":"把句子讀明白","body":"先找到 whose 後面的名詞：誰的子女／哪個物件的部分？再找它是單數還是複數。"},{"title":"針對這句的錯法或疑問","body":"whose 也可介紹建築物的部分，不限人物。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：We stayed in a building who''s roof was damaged. → We stayed in a building whose roof was damaged.。因為whose 可用於建築物的部分。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面的名詞是誰的？如果試用 who’s，展開成 who is／who has 還能讀通嗎？"}]'::jsonb),
  (105, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"關係子句把介詞放前面時，指物通常用 in which／on which／with which，不能直接用 in that 代替。但 the room that we met in 可以，因為介詞放在最後。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The folder in which I stored my notes is missing.。in which 表示把筆記放在文件夾內，介詞與物件的關係正確。看它怎樣處理「that → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (106, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"that 是 barked 的主語，標準書面語須保留。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The singer whom sings the final song is my cousin. → The singer who sings the final song is my cousin.。因為sings 前的關係字作主語須用 who。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (107, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"talk to her 表對象，talk about 表主題，兩組介詞各有工作。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：That is the issue that we talked to her about. ✓。你可以先把句中介紹的部分拿走，再放回來；talk to her 表對象，talk about 表主題，兩組介詞各有工作。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (108, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"visit／explore 直接接受詞：we visited the museum，不是 we visited in the museum。所以介紹被參觀的地方要用 that／which（有些句子可省），where 才表示「在那裏做另一件事」。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：This is the city that I visited last summer.。visit 直接以 city 作受詞，故用 that 而非 where。看它怎樣處理「where → that」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (109, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"限定子句中 that 亦可指人，不能硬判只用於物件。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The woman that greeted the visitors teaches history. ✓。你可以先把句中介紹的部分拿走，再放回來；限定子句中 that 亦可指人，不能硬判只用於物件。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (110, '[{"title":"把句子讀明白","body":"逗號之前先說完「A visitor」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"為甚麼那個 that 不能留？ 逗號前已交代清楚對象／整件事，逗號後只是在補充。標準英文不在這類補充關係子句用 that。如果後面是在評論整件事，要用 which；如果只是接着介紹一位已知的人，用 who。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：My tablet, which is five years old, still works.。補充關係子句有逗號，要用 which 而非 that。看它怎樣處理「that → who」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (111, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"on which 是表示該日的較正式寫法。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：Monday was the day on that we moved. → Monday was the day on which we moved.。因為表示在那一天的正式關係寫法是 on which，前置介詞後不用 that。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (112, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"原句的 do you feel 在此處不合用；wherever 子句不用疑問倒裝。 正確修改是 do you feel → you feel，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：Sit wherever you feel comfortable in the hall.。wherever 表不限制坐在哪裏。看它怎樣處理「do you feel → you feel」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (113, '[{"title":"把句子讀明白","body":"She was the first visitor to arrive 是「她是第一個到達的參觀者」。was 說她當時的排名。"},{"title":"針對這句的錯法或疑問","body":"當 first／last／next 後面用 to + 動詞 說「第一位做甚麼」時，to 後要原形 arrive；過去意思已由 was 表達，不要寫成 to arrived。"},{"title":"看同一文法點的對照","body":"She was the first visitor to arrive. ✓；She arrived first. ✓；to arrived ✗。"},{"title":"下次遇到這種題怎樣自己判斷","body":"看到 to，先判斷它是不是這種「to + 動詞」接法；若是，後面寫 arrive，別把兩個動詞都改成過去式。"}]'::jsonb),
  (114, '[{"title":"把句子讀明白","body":"看看 It was ... who/that 是在強調「正是誰」，還是 the news/fact that ... 在說「消息是甚麼」。"},{"title":"針對這句的錯法或疑問","body":"All I want 帶「這就是全部需求」的語氣。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：All what I want is a quiet room. → All that I want is a quiet room.。因為All 後可用 that 或零受詞形式，不把 what 當普通關係字。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是在強調某個人，還是在說明 the news／the fact 的內容？兩種 that 的工作不同。"}]'::jsonb),
  (115, '[{"title":"把句子讀明白","body":"這句有幾個動詞？先分開找每個動詞自己的主語，不要把主句的人數或時間誤套進關係小句。"},{"title":"針對這句的錯法或疑問","body":"找出 works 自己對應哪個主語。明說五位 workers 全部輪夜班，who 回指複數 workers，故用 work。 work 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：She is one of the workers who work at night.。who 通常回指 workers 複數，故 work。看它怎樣處理「works → work」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個動詞真正的主語是單數還是複數？時間又是在過去、現在或將來？"}]'::jsonb),
  (116, '[{"title":"把句子讀明白","body":"先問後面的字是在幫忙指出「哪一個人／哪一件事」，還是在補充已知道的人／物；這會影響逗號及能否用 that。"},{"title":"針對這句的錯法或疑問","body":"原句的 museum, was 在此處不合用；限定子句不能任意以單一逗號切斷主句。 正確修改是 museum, was → museum was，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The workbook that has a yellow cover belongs to Lily.。that has a yellow cover 是必要辨識資料，通常不用逗號隔開。看它怎樣處理「museum, was → museum was」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (117, '[{"title":"把句子讀明白","body":"逗號之前先說完「We talked to Sam」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"放在句尾的補充子句只須前面一個逗號。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：We talked to Sam, who works at the museum. ✓。你可以先把句中介紹的部分拿走，再放回來；放在句尾的補充子句只須前面一個逗號。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (118, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"the one who 指人；what she said 則是事情或內容。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The one who called earlier was my sister. ✓。你可以先把句中介紹的部分拿走，再放回來；the one who 指人；what she said 則是事情或內容。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (119, '[{"title":"把句子讀明白","body":"這題專門提醒你不要把已經正確的日常寫法當錯誤；要先看真正的句意，而不是只背一條「更正式」的偏好。"},{"title":"針對這句的錯法或疑問","body":"such ... as 在較正式或古典語體可表示當時手頭有的物資。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：We shared such supplies as we had. ✓。你可以先把句中介紹的部分拿走，再放回來；such ... as 在較正式或古典語體可表示當時手頭有的物資。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是文法真的不成立，還是只是比較少見／比較正式？只有真正錯誤才打 ✗。"}]'::jsonb),
  (120, '[{"title":"把句子讀明白","body":"看看 It was ... who/that 是在強調「正是誰」，還是 the news/fact that ... 在說「消息是甚麼」。"},{"title":"針對這句的錯法或疑問","body":"wherein 是正式「在該協議中」的說法。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：They reached an agreement wherein the costs were shared. ✓。你可以先把句中介紹的部分拿走，再放回來；wherein 是正式「在該協議中」的說法。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是在強調某個人，還是在說明 the news／the fact 的內容？兩種 that 的工作不同。"}]'::jsonb),
  (121, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"notebook 是 found 的受詞，也由 that Amelia had misplaced 再加描述。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The pupil that I met her in the corridor is new. → The pupil that I met in the corridor is new.。因為that 已代表被見到的 pupil，不再加 her。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (122, '[{"title":"把句子讀明白","body":"逗號之前先說完「The concert was cancelled」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"which 指取消演唱會整件事，不是介紹 concert 的種類。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The team won the match, that delighted the coach. → The team won the match, which delighted the coach.。因為回指整件事的補充子句不能直接用 that。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (123, '[{"title":"把句子讀明白","body":"逗號之前先說完「He apologised」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"which 可指逗號前整件事：例如「比賽取消」導致球員失望；不是只說某個叫 match 的東西。這類逗號後評論／結果不能直接換成 that。"},{"title":"看同一文法點的對照","body":"原句：He apologised, which did not solve the problem. ✓。你可以先把句中介紹的部分拿走，再放回來；否定只在 did not solve；不是說他沒有道歉。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面是在評論剛剛發生的整件事，還是找哪一個人／物？前者常用逗號 which，不可直接換成 that。"}]'::jsonb),
  (124, '[{"title":"把句子讀明白","body":"先問後面的字是在幫忙指出「哪一個人／哪一件事」，還是在補充已知道的人／物；這會影響逗號及能否用 that。"},{"title":"針對這句的錯法或疑問","body":"句中原來的 they must 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；Anyone who wants ... 已作主句主語，不再多一個 they。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：Anyone who finishes early may leave quietly.。anyone 後面的 who finishes 提出條件，finishes 用單數。看它怎樣處理「they must → must」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (125, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"where 修飾 place；與 I know where the orchestra rehearses 的結構不同。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The room that the dancers practise is very large. → The room where the dancers practise is very large.。因為practise 指在房間內練習，應用 where 或 in which。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (126, '[{"title":"把句子讀明白","body":"把短描述還原成 who is doing／which was made／which is being repaired 讀一次，看看誰做、誰被做、動作是否正在發生。"},{"title":"針對這句的錯法或疑問","body":"縮短的否定分詞片語用 not wearing。 這一題只需把 not wears 改為 not wearing；不是把整句所有動詞一起換時態。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：Students not wearing badges must report to the office.。not wearing 保留「沒有佩戴」的限制。看它怎樣處理「not wears → not wearing」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (127, '[{"title":"把句子讀明白","body":"先找到 whose 後面的名詞：誰的子女／哪個物件的部分？再找它是單數還是複數。"},{"title":"針對這句的錯法或疑問","body":"找出 are 自己對應哪個主語。brother 單數，用 is。 is 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The girl whose parents work here is cheerful.。parents 是複數，關係子句用 work。看它怎樣處理「are → is」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面的名詞是誰的？如果試用 who’s，展開成 who is／who has 還能讀通嗎？"}]'::jsonb),
  (128, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"what she found 作 kept 的受詞，前面沒有另外的 thing。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：She kept what she found in the drawer. ✓。你可以先把句中介紹的部分拿走，再放回來；what she found 作 kept 的受詞，前面沒有另外的 thing。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (129, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"本句介紹的是人，而後面的動詞也是這個人在做，所以用 who。which 常介紹物件；但若是人物後面的普通限定句，that 有時也可用。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The chef who prepared the school lunch waved to us.。who 是 prepared 的主語，介紹做飯的人。看它怎樣處理「which → who」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (130, '[{"title":"把句子讀明白","body":"逗號之前先說完「My father」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"原句的 Tai Po is 在此處不合用；句中補充關係子句需要兩邊逗號。 正確修改是 Tai Po is → Tai Po, is，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：My older sister, who studies in Bristol, is visiting.。句中補充子句有前後兩個逗號。看它怎樣處理「Tai Po is → Tai Po, is」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (131, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"原句的 Maya, I 在此處不合用；補充子句即使是受詞也不能省關係字。 正確修改是 Maya, I → Maya, whom I，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：Tom, whom we met on Sunday, is a doctor.。補充子句連受詞 whom 亦不能直接省掉。看它怎樣處理「Maya, I → Maya, whom I」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (132, '[{"title":"把句子讀明白","body":"這句有幾個動詞？先分開找每個動詞自己的主語，不要把主句的人數或時間誤套進關係小句。"},{"title":"針對這句的錯法或疑問","body":"who 最自然指 boy；若要指畫像，需另外寫清楚。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：I saw the portrait of the boy who was smiling. ✓。你可以先把句中介紹的部分拿走，再放回來；who 最自然指 boy；若要指畫像，需另外寫清楚。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個動詞真正的主語是單數還是複數？時間又是在過去、現在或將來？"}]'::jsonb),
  (133, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"日常寫作可用介詞後置的清楚句型，不必刻意轉繁複。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：This is the chair that I sat on during assembly. ✓。你可以先把句中介紹的部分拿走，再放回來；日常寫作可用介詞後置的清楚句型，不必刻意轉繁複。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (134, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"when 要與前面的 time 和發生時間相配。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The morning where I began school was rainy. → The morning when I began school was rainy.。因為morning 表時間，應用 when。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (135, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"前置介詞 with 後面用 which，不用 that。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The pen with that she wrote the card was blue. → The pen with which she wrote the card was blue.。因為前置介詞 with 後須用 which。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (136, '[{"title":"把句子讀明白","body":"先找到 whose 後面的名詞：誰的子女／哪個物件的部分？再找它是單數還是複數。"},{"title":"針對這句的錯法或疑問","body":"whose brother 是音樂家的兄弟，不是音樂家本人。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：I met a teacher who daughter is in our class. → I met a teacher whose daughter is in our class.。因為女兒屬於老師，應用 whose。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面的名詞是誰的？如果試用 who’s，展開成 who is／who has 還能讀通嗎？"}]'::jsonb),
  (137, '[{"title":"把句子讀明白","body":"先問後面的字是在幫忙指出「哪一個人／哪一件事」，還是在補充已知道的人／物；這會影響逗號及能否用 that。"},{"title":"針對這句的錯法或疑問","body":"there is 用來介紹新人物，who wants 再提供資料。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：There are someone who needs help outside. → There is someone who needs help outside.。因為someone 單數，存在句用 there is。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (138, '[{"title":"把句子讀明白","body":"把短描述還原成 who is doing／which was made／which is being repaired 讀一次，看看誰做、誰被做、動作是否正在發生。"},{"title":"針對這句的錯法或疑問","body":"找出 is 自己對應哪個主語。seats 是複數；available today 是正確後置描述。 are 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The book I borrowed is on the desk.。零受詞關係字不是 -ing 分詞的省字方式。看它怎樣處理「is → are」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (139, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"關係子句把介詞放前面時，指物通常用 in which／on which／with which，不能直接用 in that 代替。但 the room that we met in 可以，因為介詞放在最後。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The hall in which we rehearsed was very quiet.。正式可把 in 放在 which 前。看它怎樣處理「that → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (140, '[{"title":"把句子讀明白","body":"這句有幾個動詞？先分開找每個動詞自己的主語，不要把主句的人數或時間誤套進關係小句。"},{"title":"針對這句的錯法或疑問","body":"have 後配過去分詞 heard；ever 可與最高級經驗並用。 這一題只需把 ever hearing 改為 ever heard；不是把整句所有動詞一起換時態。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：This is the best meal I have ever had.。最高級搭 ever 可說到目前為止的經驗。看它怎樣處理「ever hearing → ever heard」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個動詞真正的主語是單數還是複數？時間又是在過去、現在或將來？"}]'::jsonb),
  (141, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"句中原來的 did he buy 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；間接問句用主語在動詞前的陳述次序。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：I do not know what he bought yesterday.。不知道買的是甚麼，是間接問句的內容。看它怎樣處理「did he buy → he bought」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (142, '[{"title":"把句子讀明白","body":"逗號之前先說完「The event」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"本句介紹的是物件／活動而不是人，所以用 which。你不能只因為那件東西「做了某件事」（例如時鐘停了），就把它當成人用 who。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：Our school, which opened ten years ago, has a new library.。補充學校的消息用 which，不用 that。看它怎樣處理「who → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (143, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"這裏已有前面的名詞（例如 novel／book／all），後面的字只需接回它。what 常相當於「所……的東西」，不能在這種位置再塞進去；用 that，或在合適的受詞位置直接省略。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：What we need is a short break.。what 已包含「需要的事情」，不再加 the thing。看它怎樣處理「what → that」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (144, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"本句介紹的是物件／活動而不是人，所以用 which。你不能只因為那件東西「做了某件事」（例如時鐘停了），就把它當成人用 who。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The printer which broke yesterday needs a new cable.。which 指 printer；這部打印機是 broke 的主語。看它怎樣處理「who → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (145, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"受詞關係可跨過 I think，borrowed 缺的是 book。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The book I think Nina borrowed is on the desk. ✓。你可以先把句中介紹的部分拿走，再放回來；受詞關係可跨過 I think，borrowed 缺的是 book。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (146, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"本句介紹的是物件／活動而不是人，所以用 which。你不能只因為那件東西「做了某件事」（例如時鐘停了），就把它當成人用 who。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The printer which broke yesterday needs a new cable.。which 指 printer；這部打印機是 broke 的主語。看它怎樣處理「who → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (147, '[{"title":"把句子讀明白","body":"先問後面的字是在幫忙指出「哪一個人／哪一件事」，還是在補充已知道的人／物；這會影響逗號及能否用 that。"},{"title":"針對這句的錯法或疑問","body":"去掉限定子句雖可能成句，但會改變 documents 的範圍。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The documents that I checked are ready. ✓。你可以先把句中介紹的部分拿走，再放回來；去掉限定子句雖可能成句，但會改變 documents 的範圍。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (148, '[{"title":"把句子讀明白","body":"這題專門提醒你不要把已經正確的日常寫法當錯誤；要先看真正的句意，而不是只背一條「更正式」的偏好。"},{"title":"針對這句的錯法或疑問","body":"普通正式寫作用 that/which 或零形式，不用方言的名詞後 what。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The novel what I bought yesterday is interesting. → The novel that I bought yesterday is interesting.。因為普通標準關係子句在 novel 後用 that / which。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是文法真的不成立，還是只是比較少見／比較正式？只有真正錯誤才打 ✗。"}]'::jsonb),
  (149, '[{"title":"把句子讀明白","body":"逗號之前先說完「The new library」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"為甚麼那個 that 不能留？ 逗號前已交代清楚對象／整件事，逗號後只是在補充。標準英文不在這類補充關係子句用 that。如果後面是在評論整件事，要用 which；如果只是接着介紹一位已知的人，用 who。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：Our school, which opened ten years ago, has a new library.。補充學校的消息用 which，不用 that。看它怎樣處理「that → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (150, '[{"title":"把句子讀明白","body":"把短描述還原成 who is doing／which was made／which is being repaired 讀一次，看看誰做、誰被做、動作是否正在發生。"},{"title":"針對這句的錯法或疑問","body":"ready for the test 可直接後置，符合此形容詞搭配。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The students who are ready for the test they may enter. → The students who are ready for the test may enter.。因為主句的學生已是主語，不再加 they。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (151, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"受詞關係字省略，we 是 read 的主語。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The story we read in class was exciting. ✓。你可以先把句中介紹的部分拿走，再放回來；受詞關係字省略，we 是 read 的主語。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (152, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"that opens the side door 修飾 card，不是修飾 door。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The library card that opens the side door belongs to Ben. ✓。你可以先把句中介紹的部分拿走，再放回來；that opens the side door 修飾 card，不是修飾 door。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (153, '[{"title":"把句子讀明白","body":"把每一組介紹讀清楚，先問「前面的這個名詞正在做甚麼／被人做了甚麼？」；不要把別人的動詞或主句的動詞算到它身上。"},{"title":"針對這句的錯法或疑問","body":"找出 dance 自己對應哪個主語。第二個 who 仍指 girl，所以 dances。 dances 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The girl who sang and danced won the prize.。who 後的 sang 和 danced 是同一女孩兩個動作。看它怎樣處理「dance → dances」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：兩個 who／that 是否分別指不同名詞？它們後面的動詞有沒有跟錯人或物？"}]'::jsonb),
  (154, '[{"title":"把句子讀明白","body":"找 to 後面的動詞和真正做事的人：是 first runner 自己 arrive，還是有人要 sign forms？"},{"title":"針對這句的錯法或疑問","body":"novel 是被閱讀的物件，不是自己讀書的人。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：This is a novel to read during the holidays. ✓。你可以先把句中介紹的部分拿走，再放回來；novel 是被閱讀的物件，不是自己讀書的人。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：to 後動詞是否原形？要講 sit on a chair 時，那個 on 有沒有跟着保留？"}]'::jsonb),
  (155, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"限定物件時 which 與 that 都可能正確，不應因風格偏好改錯。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The film which our club watched was inspiring. ✓。你可以先把句中介紹的部分拿走，再放回來；限定物件時 which 與 that 都可能正確，不應因風格偏好改錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (156, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"what 已包含「需要的事情」，不再加 the thing。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：I ate the food what Mum prepared for us. → I ate the food that Mum prepared for us.。因為有外面的 food 時，限定用 that/which 或零形式。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (157, '[{"title":"把句子讀明白","body":"先找到 whose 後面的名詞：誰的子女／哪個物件的部分？再找它是單數還是複數。"},{"title":"針對這句的錯法或疑問","body":"句中原來的 read it 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；whose novel 已是 read 的受詞，不再重複 it。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The novelist whose book I read visited us.。whose book 是 I read 的受詞，並非作家讀我的書。看它怎樣處理「read it → read」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面的名詞是誰的？如果試用 who’s，展開成 who is／who has 還能讀通嗎？"}]'::jsonb),
  (158, '[{"title":"把句子讀明白","body":"把每一組介紹讀清楚，先問「前面的這個名詞正在做甚麼／被人做了甚麼？」；不要把別人的動詞或主句的動詞算到它身上。"},{"title":"針對這句的錯法或疑問","body":"句中原來的 they may 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；主句的學生已是主語，不再加 they。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The pupils ready for the test may enter.。ready for the test 可直接後置，符合此形容詞搭配。看它怎樣處理「they may → may」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (159, '[{"title":"把句子讀明白","body":"逗號之前先說完「Our school」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"補充學校的消息用 which，不用 that。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：Our head teacher, that welcomed the guests, smiled. → Our head teacher, who welcomed the guests, smiled.。因為有逗號補充一位人物，用 who。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (160, '[{"title":"把句子讀明白","body":"把每一組介紹讀清楚，先問「前面的這個名詞正在做甚麼／被人做了甚麼？」；不要把別人的動詞或主句的動詞算到它身上。"},{"title":"針對這句的錯法或疑問","body":"that 可以連到較裏面的 had bought 受詞；句法關係必須清楚。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：This is the novel that I said Maya had bought. ✓。你可以先把句中介紹的部分拿走，再放回來；that 可以連到較裏面的 had bought 受詞；句法關係必須清楚。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：兩個 who／that 是否分別指不同名詞？它們後面的動詞有沒有跟錯人或物？"}]'::jsonb),
  (161, '[{"title":"把句子讀明白","body":"看看 It was ... who/that 是在強調「正是誰」，還是 the news/fact that ... 在說「消息是甚麼」。"},{"title":"針對這句的錯法或疑問","body":"強調物件可用 that，不用指人的 who。 把前面的名詞代入那個關係字的位置，試讀成普通句，就可看出哪個字不合這句的意思。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：It was the blue bag that our class chose.。It was ... that 可突出指定物件。看它怎樣處理「who → that」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是在強調某個人，還是在說明 the news／the fact 的內容？兩種 that 的工作不同。"}]'::jsonb),
  (162, '[{"title":"把句子讀明白","body":"先找到 whose 後面的名詞：誰的子女／哪個物件的部分？再找它是單數還是複數。"},{"title":"針對這句的錯法或疑問","body":"女兒屬於老師，應用 whose。 把前面的名詞代入那個關係字的位置，試讀成普通句，就可看出哪個字不合這句的意思。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：I know a musician whose brother is a pilot.。whose brother 是音樂家的兄弟，不是音樂家本人。看它怎樣處理「who → whose」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面的名詞是誰的？如果試用 who’s，展開成 who is／who has 還能讀通嗎？"}]'::jsonb),
  (163, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"meet 表示在咖啡店見面，需地點關係 where 或 in which。 把前面的名詞代入那個關係字的位置，試讀成普通句，就可看出哪個字不合這句的意思。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：This is the park where our class plays football.。where 表示動作在公園發生。看它怎樣處理「which → where」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (164, '[{"title":"把句子讀明白","body":"先問後面的字是在幫忙指出「哪一個人／哪一件事」，還是在補充已知道的人／物；這會影響逗號及能否用 that。"},{"title":"針對這句的錯法或疑問","body":"a pupil who ... 可泛指符合條件的學生，不必確定特定一人。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：A pupil who feels unwell should tell a teacher. ✓。你可以先把句中介紹的部分拿走，再放回來；a pupil who ... 可泛指符合條件的學生，不必確定特定一人。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (165, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"the David 表示對這個人的某段時期印象，不是普通人名前隨意加 the。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The David I remember from primary school was shy. ✓。你可以先把句中介紹的部分拿走，再放回來；the David 表示對這個人的某段時期印象，不是普通人名前隨意加 the。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (166, '[{"title":"把句子讀明白","body":"把每一組介紹讀清楚，先問「前面的這個名詞正在做甚麼／被人做了甚麼？」；不要把別人的動詞或主句的動詞算到它身上。"},{"title":"針對這句的錯法或疑問","body":"找出 live 自己對應哪個主語。內層 who 指 brother 單數。 lives 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：I met a boy whose brother who lives in Macau is a chef.。who lives in Macau 修飾 brother，不是 boy。看它怎樣處理「live → lives」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：兩個 who／that 是否分別指不同名詞？它們後面的動詞有沒有跟錯人或物？"}]'::jsonb),
  (167, '[{"title":"把句子讀明白","body":"這句有幾個動詞？先分開找每個動詞自己的主語，不要把主句的人數或時間誤套進關係小句。"},{"title":"針對這句的錯法或疑問","body":"主句現在、關係句過去可以並存。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：I know somebody who lived in Canada several years ago. ✓。你可以先把句中介紹的部分拿走，再放回來；主句現在、關係句過去可以並存。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個動詞真正的主語是單數還是複數？時間又是在過去、現在或將來？"}]'::jsonb),
  (168, '[{"title":"把句子讀明白","body":"把每一組介紹讀清楚，先問「前面的這個名詞正在做甚麼／被人做了甚麼？」；不要把別人的動詞或主句的動詞算到它身上。"},{"title":"針對這句的錯法或疑問","body":"had lived 保留過去已完成的時間訊息，不必強改短寫法。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The student who had lived in Canada moved away last year. ✓。你可以先把句中介紹的部分拿走，再放回來；had lived 保留過去已完成的時間訊息，不必強改短寫法。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (169, '[{"title":"把句子讀明白","body":"逗號之前先說完「Our head teacher」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"為甚麼那個 that 不能留？ 逗號前已交代清楚對象／整件事，逗號後只是在補充。標準英文不在這類補充關係子句用 that。如果後面是在評論整件事，要用 which；如果只是接着介紹一位已知的人，用 who。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：Our school, which opened ten years ago, has a new library.。補充學校的消息用 which，不用 that。看它怎樣處理「that → who」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (170, '[{"title":"把句子讀明白","body":"看看 It was ... who/that 是在強調「正是誰」，還是 the news/fact that ... 在說「消息是甚麼」。"},{"title":"針對這句的錯法或疑問","body":"It was ... that 可突出指定物件。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：It was the blue bag who our class chose. → It was the blue bag that our class chose.。因為強調物件可用 that，不用指人的 who。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是在強調某個人，還是在說明 the news／the fact 的內容？兩種 that 的工作不同。"}]'::jsonb),
  (171, '[{"title":"把句子讀明白","body":"逗號之前先說完「The class was cancelled」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"which 可指逗號前整件事：例如「比賽取消」導致球員失望；不是只說某個叫 match 的東西。這類逗號後評論／結果不能直接換成 that。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The assembly ended early, that was a relief. → The assembly ended early, which was a relief.。因為評價整件提早結束，用 which。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面是在評論剛剛發生的整件事，還是找哪一個人／物？前者常用逗號 which，不可直接換成 that。"}]'::jsonb),
  (172, '[{"title":"把句子讀明白","body":"逗號之前先說完「Ben spoke to Amy」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"which 可指逗號前整件事：例如「比賽取消」導致球員失望；不是只說某個叫 match 的東西。這類逗號後評論／結果不能直接換成 that。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：Ben called Amy, who then told the organiser.。who then told 說明 Amy 接着做了甚麼。看它怎樣處理「which → who」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面是在評論剛剛發生的整件事，還是找哪一個人／物？前者常用逗號 which，不可直接換成 that。"}]'::jsonb),
  (173, '[{"title":"把句子讀明白","body":"把每一組介紹讀清楚，先問「前面的這個名詞正在做甚麼／被人做了甚麼？」；不要把別人的動詞或主句的動詞算到它身上。"},{"title":"針對這句的錯法或疑問","body":"who lives in Macau 修飾 brother，不是 boy。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The girl whose brother who live in Macau is a chef smiled. → The girl whose brother who lives in Macau is a chef smiled.。因為內層 who 指 brother 單數。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：兩個 who／that 是否分別指不同名詞？它們後面的動詞有沒有跟錯人或物？"}]'::jsonb),
  (174, '[{"title":"把句子讀明白","body":"整句的主語是一大組字：All the students who registered（所有報了名的學生）。他們做的事是 received a ticket。"},{"title":"針對這句的錯法或疑問","body":"主語已有 All the students，所以主句直接接 received；如果再寫 they received，就變成「所有已報名的學生他們收到票」，同一個主語重複一次。"},{"title":"看同一文法點的對照","body":"All the students who registered received a ticket. ✓；They received a ticket. ✓（另起一句才用 They 作主語。）"},{"title":"下次遇到這種題怎樣自己判斷","body":"把中間 who registered 遮住：All the students received a ticket，已經完整，不需要插入 they。"}]'::jsonb),
  (175, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"place 後某些地點關係可用零形式，但並非所有搭配都可。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：This is the place we used to meet after class. ✓。你可以先把句中介紹的部分拿走，再放回來；place 後某些地點關係可用零形式，但並非所有搭配都可。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (176, '[{"title":"把句子讀明白","body":"先找到 whose 後面的名詞：誰的子女／哪個物件的部分？再找它是單數還是複數。"},{"title":"針對這句的錯法或疑問","body":"whose 可出現在逗號隔開的補充子句。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：Mr Wong, whose daughter is in our class, waved. ✓。你可以先把句中介紹的部分拿走，再放回來；whose 可出現在逗號隔開的補充子句。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面的名詞是誰的？如果試用 who’s，展開成 who is／who has 還能讀通嗎？"}]'::jsonb),
  (177, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"who 是 prepared 的主語，介紹做飯的人。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The musician which played the violin won a prize. → The musician who played the violin won a prize.。因為musician 是人並作 played 的主語。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (178, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"原句的 to I 在此處不合用；前置介詞後不能直接省去關係字；也可改成 I spoke to。 正確修改是 to I → to whom I，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The teacher I spoke to was helpful.。省去受詞關係字後，speak to 的介詞仍在。看它怎樣處理「to I → to whom I」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (179, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"in which 和 where 在相應地點關係中都可成立。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The classroom in which we met was quiet. ✓。你可以先把句中介紹的部分拿走，再放回來；in which 和 where 在相應地點關係中都可成立。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (180, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"in whose 後需要所屬名詞如 house。 把前面的名詞代入那個關係字的位置，試讀成普通句，就可看出哪個字不合這句的意思。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The friend in whose house we stayed is overseas.。前置 in 後面接 whose house 整個名詞片語。看它怎樣處理「whose → whose house」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (181, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"whenever 指任何合適時候。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：Come whenever you are frees. → Come whenever you are free.。因為are 後用形容詞 free，不加 -s。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (182, '[{"title":"把句子讀明白","body":"把短描述還原成 who is doing／which was made／which is being repaired 讀一次，看看誰做、誰被做、動作是否正在發生。"},{"title":"針對這句的錯法或疑問","body":"sitting near ... 修飾最近的 girl，不是整句主語 I。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：I spoke to the girl sitting near the window. ✓。你可以先把句中介紹的部分拿走，再放回來；sitting near ... 修飾最近的 girl，不是整句主語 I。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (183, '[{"title":"把句子讀明白","body":"把每一組介紹讀清楚，先問「前面的這個名詞正在做甚麼／被人做了甚麼？」；不要把別人的動詞或主句的動詞算到它身上。"},{"title":"針對這句的錯法或疑問","body":"完整子句保留等候時長及時間關係，比強縮更清楚。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The student who had been wait for an hour left at noon. → The student who had been waiting for an hour left at noon.。因為已持續到當時的等候用 had been + -ing。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (184, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"whatever 表不限制需要哪一件東西。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：Take whatever that you need for the trip. → Take whatever you need for the trip.。因為自由關係 whatever 本身可代指任何所需東西，後面不再加 that。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (185, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"原句的 in front which 在此處不合用；in front of 為完整介詞片語。 正確修改是 in front which → in front of which，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The house in front of which we parked has been sold.。in front of 是整組介詞片語，不能拆散。看它怎樣處理「in front which → in front of which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (186, '[{"title":"把句子讀明白","body":"把短描述還原成 who is doing／which was made／which is being repaired 讀一次，看看誰做、誰被做、動作是否正在發生。"},{"title":"針對這句的錯法或疑問","body":"broken 描述已受損而現在仍存在的狀態。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The window breaked by yesterday''s storm needs repairs. → The window broken by yesterday''s storm needs repairs.。因為窗戶在風暴中被打破，過去分詞是 broken 而不是 breaked。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (187, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"這裏已有前面的名詞（例如 novel／book／all），後面的字只需接回它。what 常相當於「所……的東西」，不能在這種位置再塞進去；用 that，或在合適的受詞位置直接省略。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：What we need is a short break.。what 已包含「需要的事情」，不再加 the thing。看它怎樣處理「what → that」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (188, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"原句的 frees 在此處不合用；are 後用形容詞 free，不加 -s。 正確修改是 frees → free，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：Visit whenever you have enough time.。whenever 指任何合適時候。看它怎樣處理「frees → free」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (189, '[{"title":"把句子讀明白","body":"把短描述還原成 who is doing／which was made／which is being repaired 讀一次，看看誰做、誰被做、動作是否正在發生。"},{"title":"針對這句的錯法或疑問","body":"being repaired 強調道路正接受維修。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The bridge being repair this month is closed. → The bridge being repaired this month is closed.。因為being + 過去分詞構成正在被維修。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (190, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"in front of 是整組介詞片語，不能拆散。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：We visited the house in front which the car was parked. → We visited the house in front of which the car was parked.。因為in front of 為完整介詞片語。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (191, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"where = 在哪裏；when = 在甚麼時候。 這題前面的 day／morning／July 是時間，不是地點，故用 when。the day we met 省略 when 有時也對。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：We met in June, when the weather was warm.。逗號後的 when 補充某段時間的情況。看它怎樣處理「where → when」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (192, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"that 已代表 coat，bought 後面不再重複 it。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The laptop that I repaired it yesterday works again. → The laptop that I repaired yesterday works again.。因為that 已代表 laptop 作 repaired 的受詞。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (193, '[{"title":"把句子讀明白","body":"這題專門提醒你不要把已經正確的日常寫法當錯誤；要先看真正的句意，而不是只背一條「更正式」的偏好。"},{"title":"針對這句的錯法或疑問","body":"現代標準英文用 which，不用歷史色彩的 the which。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The house which we visited had a large garden. ✓。你可以先把句中介紹的部分拿走，再放回來；現代標準英文用 which，不用歷史色彩的 the which。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是文法真的不成立，還是只是比較少見／比較正式？只有真正錯誤才打 ✗。"}]'::jsonb),
  (194, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"practise 指在房間內練習，應用 where 或 in which。 把前面的名詞代入那個關係字的位置，試讀成普通句，就可看出哪個字不合這句的意思。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：This is the place where the orchestra rehearses.。where 修飾 place；與 I know where the orchestra rehearses 的結構不同。看它怎樣處理「that → where」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (195, '[{"title":"把句子讀明白","body":"逗號之前先說完「The trophy」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"為甚麼那個 that 不能留？ 逗號前已交代清楚對象／整件事，逗號後只是在補充。標準英文不在這類補充關係子句用 that。如果後面是在評論整件事，要用 which；如果只是接着介紹一位已知的人，用 who。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：My tablet, which is five years old, still works.。補充關係子句有逗號，要用 which 而非 that。看它怎樣處理「that → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (196, '[{"title":"把句子讀明白","body":"把短描述還原成 who is doing／which was made／which is being repaired 讀一次，看看誰做、誰被做、動作是否正在發生。"},{"title":"針對這句的錯法或疑問","body":"窗戶在風暴中被打破，過去分詞是 broken 而不是 breaked。 這一題只需把 breaked 改為 broken；不是把整句所有動詞一起換時態。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The window broken during the storm needs repair.。broken 描述已受損而現在仍存在的狀態。看它怎樣處理「breaked → broken」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (197, '[{"title":"把句子讀明白","body":"把短描述還原成 who is doing／which was made／which is being repaired 讀一次，看看誰做、誰被做、動作是否正在發生。"},{"title":"針對這句的錯法或疑問","body":"available today 是名詞後置的形容詞片語。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The chairs available this afternoon is beside the door. → The chairs available this afternoon are beside the door.。因為chairs 複數主語，所以用 are。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (198, '[{"title":"把句子讀明白","body":"逗號之前先說完「The road was closed」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"為甚麼那個 that 不能留？ 逗號前已交代清楚對象／整件事，逗號後只是在補充。標準英文不在這類補充關係子句用 that。如果後面是在評論整件事，要用 which；如果只是接着介紹一位已知的人，用 who。"},{"title":"看同一文法點的對照","body":"The road was closed, which made us late. ✓；The road that leads to school was closed. ✓（一個說結果，一個分辨哪條路。）"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面是在評論剛剛發生的整件事，還是找哪一個人／物？前者常用逗號 which，不可直接換成 that。"}]'::jsonb),
  (199, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"逗號後的 when 補充某段時間的情況。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：We held the school fair in July, where the weather was warm. → We held the school fair in July, when the weather was warm.。因為July 是月份，補充時間要用 when。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (200, '[{"title":"把句子讀明白","body":"逗號之前先說完「Our school」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"為甚麼那個 that 不能留？ 逗號前已交代清楚對象／整件事，逗號後只是在補充。標準英文不在這類補充關係子句用 that。如果後面是在評論整件事，要用 which；如果只是接着介紹一位已知的人，用 who。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：Our school, which opened ten years ago, has a new library.。補充學校的消息用 which，不用 that。看它怎樣處理「that → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (201, '[{"title":"把句子讀明白","body":"把短描述還原成 who is doing／which was made／which is being repaired 讀一次，看看誰做、誰被做、動作是否正在發生。"},{"title":"針對這句的錯法或疑問","body":"made by 表示被製作的蛋糕，並可說明製作者。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The cookies making by Mum smell wonderful. → The cookies made by Mum smell wonderful.。因為cookies 是被製作的物品，用 made by。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (202, '[{"title":"把句子讀明白","body":"先問後面的字是在幫忙指出「哪一個人／哪一件事」，還是在補充已知道的人／物；這會影響逗號及能否用 that。"},{"title":"針對這句的錯法或疑問","body":"句中原來的 which it 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；破折號中的 which 已作被動主語，不重複 it。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The bridge—which was repaired last year—is now safe.。破折號可像一對逗號，把補充內容夾在中間。看它怎樣處理「which it → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (203, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"原句的 on that 在此處不合用；表示在那一天的正式關係寫法是 on which，前置介詞後不用 that。 正確修改是 on that → on which，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：Monday was the day on which we opened the exhibition.。on which 是表示該日的較正式寫法。看它怎樣處理「on that → on which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (204, '[{"title":"把句子讀明白","body":"逗號之前先說完「She won the scholarship」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"which 可指逗號前整件事：例如「比賽取消」導致球員失望；不是只說某個叫 match 的東西。這類逗號後評論／結果不能直接換成 that。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The road was closed, that delayed the bus. → The road was closed, which delayed the bus.。因為回指整件道路關閉的事用 which。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面是在評論剛剛發生的整件事，還是找哪一個人／物？前者常用逗號 which，不可直接換成 that。"}]'::jsonb),
  (205, '[{"title":"把句子讀明白","body":"把短描述還原成 who is doing／which was made／which is being repaired 讀一次，看看誰做、誰被做、動作是否正在發生。"},{"title":"針對這句的錯法或疑問","body":"being + 過去分詞構成正在被維修。 這一題只需把 repair 改為 repaired；不是把整句所有動詞一起換時態。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The road being repaired is closed to traffic.。being repaired 強調道路正接受維修。看它怎樣處理「repair → repaired」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (206, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"which 是 stopped 的主語，不是人在做事。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The programme which it was created by our club is useful. → The programme which was created by our club is useful.。因為which 已是 was created 的被動主語。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (207, '[{"title":"把句子讀明白","body":"先找到 whose 後面的名詞：誰的子女／哪個物件的部分？再找它是單數還是複數。"},{"title":"針對這句的錯法或疑問","body":"原句的 surface which 在此處不合用；用 the surface of which 表示橋的表面。 正確修改是 surface which → surface of which，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The bridge, the surface of which is old, needs repairs.。the surface of which 是正式的物件所屬結構。看它怎樣處理「surface which → surface of which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面的名詞是誰的？如果試用 who’s，展開成 who is／who has 還能讀通嗎？"}]'::jsonb),
  (208, '[{"title":"把句子讀明白","body":"先問後面的字是在幫忙指出「哪一個人／哪一件事」，還是在補充已知道的人／物；這會影響逗號及能否用 that。"},{"title":"針對這句的錯法或疑問","body":"破折號可像一對逗號，把補充內容夾在中間。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The bridge—which it was repaired recently—is safe. → The bridge—which was repaired recently—is safe.。因為破折號中的 which 已作被動主語，不重複 it。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (209, '[{"title":"把句子讀明白","body":"逗號之前先說完「The road was closed」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"which 可指逗號前整件事：例如「比賽取消」導致球員失望；不是只說某個叫 match 的東西。這類逗號後評論／結果不能直接換成 that。"},{"title":"看同一文法點的對照","body":"The road was closed, which made us late. ✓；The road that leads to school was closed. ✓（一個說結果，一個分辨哪條路。）"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面是在評論剛剛發生的整件事，還是找哪一個人／物？前者常用逗號 which，不可直接換成 that。"}]'::jsonb),
  (210, '[{"title":"把句子讀明白","body":"先找到 whose 後面的名詞：誰的子女／哪個物件的部分？再找它是單數還是複數。"},{"title":"針對這句的錯法或疑問","body":"who’s = who is 或 who has，不能表「某人的」。這句後面跟母親／單車／設計，所以必須寫 whose。試展開 who’s 就會知道原句讀不通。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：We visited a building whose roof was damaged.。whose 也可介紹建築物的部分，不限人物。看它怎樣處理「who''s → whose」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面的名詞是誰的？如果試用 who’s，展開成 who is／who has 還能讀通嗎？"}]'::jsonb),
  (211, '[{"title":"把句子讀明白","body":"逗號之前先說完「Our dog」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"把熟悉寵物當作有個性的成員時 who 可以成立。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：Our cat, that sleeps beside my desk, is gentle. → Our cat, who sleeps beside my desk, is gentle.。因為補充寵物的資訊可用 who 或 which，不用 that。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (212, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"whom 通常不是做事的主語。這裏是「那個人安排／唱歌／知道答案」，即 who arranged／who sings／who is ...；I think 只是中間的說話者看法，不會把 who 變成受詞。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The nurse who checked the students was very patient.。who 指護士，而護士就是 checked 的人。看它怎樣處理「whom → who」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (213, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"句中原來的 repaired it 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；that 已代表 laptop 作 repaired 的受詞。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The coat that I bought is warm enough for winter.。that 已代表 coat，bought 後面不再重複 it。看它怎樣處理「repaired it → repaired」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (214, '[{"title":"把句子讀明白","body":"先還原成 I sent the email to the tutor（我寄電郵給導師）。「to」表示收信對象。"},{"title":"針對這句的錯法或疑問","body":"把 tutor 移到前面來介紹後，正式寫法用 to whom I sent the email。to whom 不是「有兩個 to」；若把介詞留在句尾，也可寫 who I sent the email to。"},{"title":"看同一文法點的對照","body":"The tutor to whom I sent the email replied. ✓；The tutor who I sent the email to replied. ✓。"},{"title":"下次遇到這種題怎樣自己判斷","body":"試讀 I sent the email __ the tutor。原句需要 to，所以把 tutor 前移後，to 仍要保留。"}]'::jsonb),
  (215, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"whatever tools 是一組，限定物件類別。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：Bring whatever tools you needs. → Bring whatever tools you need.。因為you 作主語，動詞用 need。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (216, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"What ... said 整組當主語，指教練說的內容。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：What the teacher said were helpful. → What the teacher said was helpful.。因為what 子句整組指一件事情或訊息，通常用 was。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (217, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"句中原來的 with it 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；that 已連接 tool，介詞 with 後不能重複同一工具的 it。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：This is the topic I was talking about.。零受詞關係字後，about 仍要保留。看它怎樣處理「with it → with」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (218, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"sit on a chair 與 sit in a room 所用介詞不同。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The seat that I sat on it was very hard. → The seat that I sat on was very hard.。因為that 指 seat，介詞 on 仍保留，但不再加 it。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (219, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"whom 通常不是做事的主語。這裏是「那個人安排／唱歌／知道答案」，即 who arranged／who sings／who is ...；I think 只是中間的說話者看法，不會把 who 變成受詞。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The woman who I think is responsible has arrived.。在 is responsible 裏，woman 是主語；I think 只是插入語。看它怎樣處理「whom → who」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (220, '[{"title":"把句子讀明白","body":"先把插入的補充拿掉：The bridge needs repairs／The folder is locked。再把補充放回去：the surface／contents of which 是「橋面／文件夾內容」，不是整條橋／整個文件夾在做動作。"},{"title":"針對這句的錯法或疑問","body":"of which 沒有錯。 它相當於 whose surface / whose contents，意思是「那個物件的表面／內容」。這兩種都合乎現代標準英文；不應只因 of which 較正式而打 ✗。"},{"title":"看同一文法點的對照","body":"The bridge, whose surface is old, needs repairs. ✓；The bridge, the surface of which is old, needs repairs. ✓。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面的名詞是誰的？如果試用 who’s，展開成 who is／who has 還能讀通嗎？"}]'::jsonb),
  (221, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"原句的 whom I wrote 在此處不合用；write to someone 表示寫信給對方。要保留句尾的 to。 正確修改是 whom I wrote → whom I wrote to，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The neighbour who I waited for is now here.。who 代表 wait for 的對象；介詞 for 要保留。看它怎樣處理「whom I wrote → whom I wrote to」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (222, '[{"title":"把句子讀明白","body":"把短描述還原成 who is doing／which was made／which is being repaired 讀一次，看看誰做、誰被做、動作是否正在發生。"},{"title":"針對這句的錯法或疑問","body":"working at night 可以描述一類人，不一定只是此刻正在做。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：People working at home needs a quiet room. → People working at home need a quiet room.。因為People 複數，主句動詞用 need。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (223, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"關係子句把介詞放前面時，指物通常用 in which／on which／with which，不能直接用 in that 代替。但 the room that we met in 可以，因為介詞放在最後。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The subject about which they argued was important.。前置 about 後面是 which，不直接接 that。看它怎樣處理「that → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (224, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"前面寫的是 the reason（原因），不是地點。要介紹離開或遲到的原因，用 why；普通英文中 the reason why... 和 the reason ... 兩種都可成立。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：That is the reason why I stayed at school.。why 引出與 reason 有關的內容。看它怎樣處理「where → why」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (225, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"reason 後可以不寫 why。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：I understand the reason because she was upset. → I understand the reason why she was upset.。因為這裏 reason 後需關係用法 why，而不是直接用 because 接關係描述。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (226, '[{"title":"把句子讀明白","body":"把每一組介紹讀清楚，先問「前面的這個名詞正在做甚麼／被人做了甚麼？」；不要把別人的動詞或主句的動詞算到它身上。"},{"title":"針對這句的錯法或疑問","body":"that 最後連到 hear 的受詞 song。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The story that I said you should reads is fascinating. → The story that I said you should read is fascinating.。因為should 後用原形 read。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：兩個 who／that 是否分別指不同名詞？它們後面的動詞有沒有跟錯人或物？"}]'::jsonb),
  (227, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"reason 後面的 why 可省去，意思保留。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The reason he left was that the room were noisy. → The reason he left was that the room was noisy.。因為that the room was noisy 以完整句子說明原因；room 單數用 was。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (228, '[{"title":"把句子讀明白","body":"把每一組介紹讀清楚，先問「前面的這個名詞正在做甚麼／被人做了甚麼？」；不要把別人的動詞或主句的動詞算到它身上。"},{"title":"針對這句的錯法或疑問","body":"who 緊接 woman，是常見而清楚的次序。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：A woman who knew the answer raised her hand. ✓。你可以先把句中介紹的部分拿走，再放回來；who 緊接 woman，是常見而清楚的次序。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：兩個 who／that 是否分別指不同名詞？它們後面的動詞有沒有跟錯人或物？"}]'::jsonb),
  (229, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"reason why 在普通標準英文中可以使用，並非必定重複錯誤。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：I understand the reason why she stayed. ✓。你可以先把句中介紹的部分拿走，再放回來；reason why 在普通標準英文中可以使用，並非必定重複錯誤。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (230, '[{"title":"把句子讀明白","body":"先問後面的字是在幫忙指出「哪一個人／哪一件事」，還是在補充已知道的人／物；這會影響逗號及能否用 that。"},{"title":"針對這句的錯法或疑問","body":"only 表示符合 knew the answer 的只有那位學生。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The only person whom knew the answer was Lee. → The only person who knew the answer was Lee.。因為唯一知道的人是 knew 的主語。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (231, '[{"title":"把句子讀明白","body":"先問後面的字是在幫忙指出「哪一個人／哪一件事」，還是在補充已知道的人／物；這會影響逗號及能否用 that。"},{"title":"針對這句的錯法或疑問","body":"whom 通常不是做事的主語。這裏是「那個人安排／唱歌／知道答案」，即 who arranged／who sings／who is ...；I think 只是中間的說話者看法，不會把 who 變成受詞。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The only pupil who knew the answer was Eva.。only 表示符合 knew the answer 的只有那位學生。看它怎樣處理「whom → who」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (232, '[{"title":"把句子讀明白","body":"這題專門提醒你不要把已經正確的日常寫法當錯誤；要先看真正的句意，而不是只背一條「更正式」的偏好。"},{"title":"針對這句的錯法或疑問","body":"介詞 to 放句尾完全可以合乎標準英文。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The village from that my grandfather came is quiet. → The village from which my grandfather came is quiet.。因為前置介詞 from 後用 which。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是文法真的不成立，還是只是比較少見／比較正式？只有真正錯誤才打 ✗。"}]'::jsonb),
  (233, '[{"title":"把句子讀明白","body":"找 to 後面的動詞和真正做事的人：是 first runner 自己 arrive，還是有人要 sign forms？"},{"title":"針對這句的錯法或疑問","body":"to answer 說明哪些電郵需要處理，不一定表示必須。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：I have many forms to signing today. → I have many forms to sign today.。因為to 不定詞後用原形 sign。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：to 後動詞是否原形？要講 sit on a chair 時，那個 on 有沒有跟着保留？"}]'::jsonb),
  (234, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"原句的 were 在此處不合用；what 子句整組指一件事情或訊息，通常用 was。 正確修改是 were → was，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：What the coach said made us laugh.。What ... said 整組當主語，指教練說的內容。看它怎樣處理「were → was」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (235, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"原句的 because 在此處不合用；這裏 reason 後需關係用法 why，而不是直接用 because 接關係描述。 正確修改是 because → why，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The reason I called was to thank you.。reason 後可以不寫 why。看它怎樣處理「because → why」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (236, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"why 引出與 reason 有關的內容。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The reason where I stayed is simple. → The reason why I stayed is simple.。因為reason 表原因，不是地點。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (237, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"前面寫的是 the reason（原因），不是地點。要介紹離開或遲到的原因，用 why；普通英文中 the reason why... 和 the reason ... 兩種都可成立。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The time when the concert begins has changed.。when 要與前面的 time 和發生時間相配。看它怎樣處理「where → why」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (238, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"原句的 were 在此處不合用；that the room was noisy 以完整句子說明原因；room 單數用 was。 正確修改是 were → was，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：Please explain the reason you left early.。reason 後面的 why 可省去，意思保留。看它怎樣處理「were → was」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (239, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"這是「不論誰來電」的讓步條件，不等於主語名詞片語。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：Whoever calls, do not give out your password. ✓。你可以先把句中介紹的部分拿走，再放回來；這是「不論誰來電」的讓步條件，不等於主語名詞片語。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (240, '[{"title":"把句子讀明白","body":"找 to 後面的動詞和真正做事的人：是 first runner 自己 arrive，還是有人要 sign forms？"},{"title":"針對這句的錯法或疑問","body":"原句的 speaks 在此處不合用；to 後主動詞保持原形。 正確修改是 speaks → speak，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：She is the next person to speak at the meeting.。next person to speak 表示輪到她發言。看它怎樣處理「speaks → speak」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：to 後動詞是否原形？要講 sit on a chair 時，那個 on 有沒有跟着保留？"}]'::jsonb),
  (241, '[{"title":"把句子讀明白","body":"I need someone to talk to about the problem 是「我需要一個可以跟他談問題的人」。"},{"title":"針對這句的錯法或疑問","body":"這是名詞後的 to + 動詞原形 描述（someone to talk to）。你不需要在第一個 to 前多寫 whom；但最後那個 to 要保留，因為是 talk to someone。"},{"title":"看同一文法點的對照","body":"someone to talk to ✓；someone whom I can talk to ✓（改成完整關係句就可以用 whom，但要有 I can）；someone whom to talk to ✗。"},{"title":"下次遇到這種題怎樣自己判斷","body":"在句子中找兩個 to：第一個是「to talk」，第二個是 talk to someone 的介詞。不要再硬塞 whom。"}]'::jsonb),
  (242, '[{"title":"把句子讀明白","body":"逗號之前先說完「Ben missed the bus」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"為甚麼那個 that 不能留？ 逗號前已交代清楚對象／整件事，逗號後只是在補充。標準英文不在這類補充關係子句用 that。如果後面是在評論整件事，要用 which；如果只是接着介紹一位已知的人，用 who。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：He missed the last bus, which upset him.。which 評論錯過巴士整件事，而不一定指巴士本身。看它怎樣處理「that → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (243, '[{"title":"把句子讀明白","body":"先問後面的字是在幫忙指出「哪一個人／哪一件事」，還是在補充已知道的人／物；這會影響逗號及能否用 that。"},{"title":"針對這句的錯法或疑問","body":"who 子句可有將來 will，不需要機械改現在式。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The guests who will arrive tomorrow need name tags. ✓。你可以先把句中介紹的部分拿走，再放回來；who 子句可有將來 will，不需要機械改現在式。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (244, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"原句的 waited 在此處不合用；wait for 的 for 不可漏。 正確修改是 waited → waited for，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The neighbour who I waited for is now here.。who 代表 wait for 的對象；介詞 for 要保留。看它怎樣處理「waited → waited for」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (245, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"句中原來的 they received 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；完整主句已有 The students 作主語，不要重複 they。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The child who won the science prize is smiling.。主句的 is smiling 不可因中間有 who won 就漏掉。看它怎樣處理「they received → received」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (246, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"原句的 that sent 在此處不合用；parcel 是被寄送而不是自己寄送。 正確修改是 that sent → that was sent，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The letter that was posted yesterday has arrived.。that 代表接受寄送的信，was posted 是被動語態。看它怎樣處理「that sent → that was sent」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (247, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"限定用途的 that 可以介紹巴士等物件，也可介紹人。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The bus that passes our school stops at the station. ✓。你可以先把句中介紹的部分拿走，再放回來；限定用途的 that 可以介紹巴士等物件，也可介紹人。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (248, '[{"title":"把句子讀明白","body":"看看 It was ... who/that 是在強調「正是誰」，還是 the news/fact that ... 在說「消息是甚麼」。"},{"title":"針對這句的錯法或疑問","body":"強調句中受詞 that 在合適情況可省去。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：It was Mia I saw at the station. ✓。你可以先把句中介紹的部分拿走，再放回來；強調句中受詞 that 在合適情況可省去。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是在強調某個人，還是在說明 the news／the fact 的內容？兩種 that 的工作不同。"}]'::jsonb),
  (249, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"句中原來的 which it 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；which 已是 stops 的主語，不必另寫 it。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The girl who helped me works in the office.。who 已是 helped 的主語，毋須另寫 she。看它怎樣處理「which it → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (250, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"visit／explore 直接接受詞：we visited the museum，不是 we visited in the museum。所以介紹被參觀的地方要用 that／which（有些句子可省），where 才表示「在那裏做另一件事」。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：This is the city that I visited last summer.。visit 直接以 city 作受詞，故用 that 而非 where。看它怎樣處理「where → that」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (251, '[{"title":"把句子讀明白","body":"這題專門提醒你不要把已經正確的日常寫法當錯誤；要先看真正的句意，而不是只背一條「更正式」的偏好。"},{"title":"針對這句的錯法或疑問","body":"現代寫作可用 to which，古舊 whither 是閱讀辨認詞。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：We went to the town to which they had moved. ✓。你可以先把句中介紹的部分拿走，再放回來；現代寫作可用 to which，古舊 whither 是閱讀辨認詞。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是文法真的不成立，還是只是比較少見／比較正式？只有真正錯誤才打 ✗。"}]'::jsonb),
  (252, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"有逗號的補充子句不可直接刪掉 whom。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The picture, I bought yesterday, looks lovely. → The picture, which I bought yesterday, looks lovely.。因為補充子句不能直接省略受詞 which。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (253, '[{"title":"把句子讀明白","body":"把每一組介紹讀清楚，先問「前面的這個名詞正在做甚麼／被人做了甚麼？」；不要把別人的動詞或主句的動詞算到它身上。"},{"title":"針對這句的錯法或疑問","body":"較長的關係子句有時後置；這是特殊但可成立的次序。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：A visitor arrived who had travelled all night. ✓。你可以先把句中介紹的部分拿走，再放回來；較長的關係子句有時後置；這是特殊但可成立的次序。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：兩個 who／that 是否分別指不同名詞？它們後面的動詞有沒有跟錯人或物？"}]'::jsonb),
  (254, '[{"title":"把句子讀明白","body":"逗號之前先說完「The train arrives at six」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"which 可指逗號前整件事：例如「比賽取消」導致球員失望；不是只說某個叫 match 的東西。這類逗號後評論／結果不能直接換成 that。"},{"title":"看同一文法點的對照","body":"原句：The train arrives at six, which is perfect for us. ✓。你可以先把句中介紹的部分拿走，再放回來；接在句尾的 which 對剛說的安排作評價；口語有時另起一句。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面是在評論剛剛發生的整件事，還是找哪一個人／物？前者常用逗號 which，不可直接換成 that。"}]'::jsonb),
  (255, '[{"title":"把句子讀明白","body":"逗號之前先說完「The train arrives at nine」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"為甚麼那個 that 不能留？ 逗號前已交代清楚對象／整件事，逗號後只是在補充。標準英文不在這類補充關係子句用 that。如果後面是在評論整件事，要用 which；如果只是接着介紹一位已知的人，用 who。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：She won the scholarship, which made her family proud.。指整件事時用 which，不應直接換成 that。看它怎樣處理「that → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面是在評論剛剛發生的整件事，還是找哪一個人／物？前者常用逗號 which，不可直接換成 that。"}]'::jsonb),
  (256, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"原句的 taking 在此處不合用；疑問詞加 to 不定詞仍用原形。 正確修改是 taking → take，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：I do not know which bus to take.。which bus to take 是不知道的內容，並非普通關係子句。看它怎樣處理「taking → take」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：to 後動詞是否原形？要講 sit on a chair 時，那個 on 有沒有跟着保留？"}]'::jsonb),
  (257, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"whom 是被 invited 的人，屬較正式的受詞形式。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The colleague whom we invited arrived before nine. ✓。你可以先把句中介紹的部分拿走，再放回來；whom 是被 invited 的人，屬較正式的受詞形式。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (258, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"which bus to take 是不知道的內容，並非普通關係子句。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：I don''t know which bus to taking. → I don''t know which bus to take.。因為疑問詞加 to 不定詞仍用原形。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：to 後動詞是否原形？要講 sit on a chair 時，那個 on 有沒有跟着保留？"}]'::jsonb),
  (259, '[{"title":"把句子讀明白","body":"這題專門提醒你不要把已經正確的日常寫法當錯誤；要先看真正的句意，而不是只背一條「更正式」的偏好。"},{"title":"針對這句的錯法或疑問","body":"as is often the case 是整組補充評論，並非拼寫錯誤。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The bus was late, as is often the case. ✓。你可以先把句中介紹的部分拿走，再放回來；as is often the case 是整組補充評論，並非拼寫錯誤。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是文法真的不成立，還是只是比較少見／比較正式？只有真正錯誤才打 ✗。"}]'::jsonb),
  (260, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"does not stop 只否定巴士在本站停靠。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The bus that does not stop here goes to the airport. ✓。你可以先把句中介紹的部分拿走，再放回來；does not stop 只否定巴士在本站停靠。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (261, '[{"title":"把句子讀明白","body":"看看 It was ... who/that 是在強調「正是誰」，還是 the news/fact that ... 在說「消息是甚麼」。"},{"title":"針對這句的錯法或疑問","body":"to put the books on 說明桌子的用途，on 不可漏。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：We have a table to put the books on. ✓。你可以先把句中介紹的部分拿走，再放回來；to put the books on 說明桌子的用途，on 不可漏。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是在強調某個人，還是在說明 the news／the fact 的內容？兩種 that 的工作不同。"}]'::jsonb),
  (262, '[{"title":"把句子讀明白","body":"逗號之前先說完「She remembered my birthday」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"which 可指逗號前整件事：例如「比賽取消」導致球員失望；不是只說某個叫 match 的東西。這類逗號後評論／結果不能直接換成 that。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：She remembered my birthday, that was thoughtful. → She remembered my birthday, which was thoughtful.。因為which 評價記得生日整件事，不用 that。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面是在評論剛剛發生的整件事，還是找哪一個人／物？前者常用逗號 which，不可直接換成 that。"}]'::jsonb),
  (263, '[{"title":"把句子讀明白","body":"找 to 後面的動詞和真正做事的人：是 first runner 自己 arrive，還是有人要 sign forms？"},{"title":"針對這句的錯法或疑問","body":"被動 to be + 過去分詞 signed。 這一題只需把 signing 改為 signed；不是把整句所有動詞一起換時態。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：These are the forms to be signed before Friday.。to be signed 是待人簽署的被動形式。看它怎樣處理「signing → signed」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：to 後動詞是否原形？要講 sit on a chair 時，那個 on 有沒有跟着保留？"}]'::jsonb),
  (264, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"that Dad borrowed 依附 book；主句仍有自己的動詞 is。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The book that Dad borrowed is surprisingly useful. ✓。你可以先把句中介紹的部分拿走，再放回來；that Dad borrowed 依附 book；主句仍有自己的動詞 is。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (265, '[{"title":"把句子讀明白","body":"把 news／fact 後面當作「消息／事實的內容」讀一次：例如 the school will close 是一整件事，並不是一個欠了受詞的動作。"},{"title":"針對這句的錯法或疑問","body":"這裏的 that 後面是完整內容（例如「學校會關閉」）；它說的是消息／事實「是甚麼」。what 不可直接代替這個連接用的 that。試比較 The news that she reported，那裏的 that 反倒成為 reported 的受詞。"},{"title":"看同一文法點的對照","body":"The news that the school will close upset us. ✓；The news that she reported upset us. ✓；第一句說內容，第二句說哪則消息。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是在強調某個人，還是在說明 the news／the fact 的內容？兩種 that 的工作不同。"}]'::jsonb),
  (266, '[{"title":"把句子讀明白","body":"把短描述還原成 who is doing／which was made／which is being repaired 讀一次，看看誰做、誰被做、動作是否正在發生。"},{"title":"針對這句的錯法或疑問","body":"零受詞關係字不是 -ing 分詞的省字方式。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The seats available today is near the stage. → The seats available today are near the stage.。因為seats 是複數；available today 是正確後置描述。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (267, '[{"title":"把句子讀明白","body":"先問後面的字是在幫忙指出「哪一個人／哪一件事」，還是在補充已知道的人／物；這會影響逗號及能否用 that。"},{"title":"針對這句的錯法或疑問","body":"原句的 here waved 在此處不合用；whose 補充子句完結時要有逗號。 正確修改是 here waved → here, waved，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：My older sister, who studies in Bristol, is visiting.。句中補充子句有前後兩個逗號。看它怎樣處理「here waved → here, waved」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (268, '[{"title":"把句子讀明白","body":"把短描述還原成 who is doing／which was made／which is being repaired 讀一次，看看誰做、誰被做、動作是否正在發生。"},{"title":"針對這句的錯法或疑問","body":"cookies 是被製作的物品，用 made by。 這一題只需把 making 改為 made；不是把整句所有動詞一起換時態。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The cake made by my father was delicious.。made by 表示被製作的蛋糕，並可說明製作者。看它怎樣處理「making → made」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (269, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"whichever 在已知選項中任選。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：Choose whichever book you likes. → Choose whichever book you like.。因為you 是 like 的主語，故用 like。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (270, '[{"title":"把句子讀明白","body":"The book I bought that you recommended 其實在說同一本書的兩件事：我買了它；你推薦過它。"},{"title":"針對這句的錯法或疑問","body":"第一段 I bought 省去作受詞的 that；第二段 that you recommended 明寫 that。兩段都介紹 book，並不是無端多放一個 that，所以文法上可成立，但讀起來比較繞。"},{"title":"看同一文法點的對照","body":"The book that you recommended and that I bought is excellent. ✓（較清楚）；The book I bought that you recommended is excellent. ✓（原句也成立）。"},{"title":"下次遇到這種題怎樣自己判斷","body":"每遇到一段關係句，就問：「它指的是否仍是同一本 book？」若是，便不能只因句子長就判錯。"}]'::jsonb),
  (271, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"正式的 on which to write 表示寫作主題。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：This is a subject on that to write an essay. → This is a subject on which to write an essay.。因為正式 on which to write 用 which。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：to 後動詞是否原形？要講 sit on a chair 時，那個 on 有沒有跟着保留？"}]'::jsonb),
  (272, '[{"title":"把句子讀明白","body":"這句有幾個動詞？先分開找每個動詞自己的主語，不要把主句的人數或時間誤套進關係小句。"},{"title":"針對這句的錯法或疑問","body":"has finished 強調到現在已完成。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The woman who have finished the report may leave. → The woman who has finished the report may leave.。因為woman 單數，完成式用 has。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個動詞真正的主語是單數還是複數？時間又是在過去、現在或將來？"}]'::jsonb),
  (273, '[{"title":"把句子讀明白","body":"先問後面的字是在幫忙指出「哪一個人／哪一件事」，還是在補充已知道的人／物；這會影響逗號及能否用 that。"},{"title":"針對這句的錯法或疑問","body":"all 的範圍限於 registered 的孩子，不一定是所有孩子。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：All the students who registered they received a ticket. → All the students who registered received a ticket.。因為全體限定主語已有 All the students，不需 they。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (274, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"關係子句把介詞放前面時，指物通常用 in which／on which／with which，不能直接用 in that 代替。但 the room that we met in 可以，因為介詞放在最後。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：This is the pen with which I signed the form.。前置介詞 with 後面用 which，不用 that。看它怎樣處理「that → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (275, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"原句的 likes 在此處不合用；you 是 like 的主語，故用 like。 正確修改是 likes → like，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：Choose whichever you prefer from these three books.。whichever 在已知選項中任選。看它怎樣處理「likes → like」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (276, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"關係子句把介詞放前面時，指物通常用 in which／on which／with which，不能直接用 in that 代替。但 the room that we met in 可以，因為介詞放在最後。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：This is a topic on which to write an essay.。正式的 on which to write 表示寫作主題。看它怎樣處理「that → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：to 後動詞是否原形？要講 sit on a chair 時，那個 on 有沒有跟着保留？"}]'::jsonb),
  (277, '[{"title":"把句子讀明白","body":"這句有幾個動詞？先分開找每個動詞自己的主語，不要把主句的人數或時間誤套進關係小句。"},{"title":"針對這句的錯法或疑問","body":"句中原來的 yesterday him 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；who 已是 called 的主語；him 在此既無適當位置也無所需受詞。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：I did not meet the person who called yesterday.。did not meet 否定見面，不是否定那人打電話。看它怎樣處理「yesterday him → yesterday」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個動詞真正的主語是單數還是複數？時間又是在過去、現在或將來？"}]'::jsonb),
  (278, '[{"title":"把句子讀明白","body":"把 news／fact 後面當作「消息／事實的內容」讀一次：例如 the school will close 是一整件事，並不是一個欠了受詞的動作。"},{"title":"針對這句的錯法或疑問","body":"that 說明消息內容，後面 the school will close 已是完整小句。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The news what the school will close upset us. → The news that the school will close upset us.。因為news 後 that 引出消息內容，what 不對。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是在強調某個人，還是在說明 the news／the fact 的內容？兩種 that 的工作不同。"}]'::jsonb),
  (279, '[{"title":"把句子讀明白","body":"看看 It was ... who/that 是在強調「正是誰」，還是 the news/fact that ... 在說「消息是甚麼」。"},{"title":"針對這句的錯法或疑問","body":"It was ... who 特別強調動作由 May 做。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：It was Mia whom found the lost wallet. → It was Mia who found the lost wallet.。因為強調做事的人，found 的主語用 who。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是在強調某個人，還是在說明 the news／the fact 的內容？兩種 that 的工作不同。"}]'::jsonb),
  (280, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"教師是人物，who 是 works 的主語。 把前面的名詞代入那個關係字的位置，試讀成普通句，就可看出哪個字不合這句的意思。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The nurse who checked the students was very patient.。who 指護士，而護士就是 checked 的人。看它怎樣處理「where → who」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (281, '[{"title":"把句子讀明白","body":"先找到 whose 後面的名詞：誰的子女／哪個物件的部分？再找它是單數還是複數。"},{"title":"針對這句的錯法或疑問","body":"whose son 是 studies 的主語，故用單數。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The woman whose son studies here teaches English. ✓。你可以先把句中介紹的部分拿走，再放回來；whose son 是 studies 的主語，故用單數。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面的名詞是誰的？如果試用 who’s，展開成 who is／who has 還能讀通嗎？"}]'::jsonb),
  (282, '[{"title":"把句子讀明白","body":"逗號之前先說完「My tablet」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"補充關係子句有逗號，要用 which 而非 that。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：My computer, that has a broken screen, still starts. → My computer, which has a broken screen, still starts.。因為有逗號的物件補充子句用 which。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (283, '[{"title":"把句子讀明白","body":"這題專門提醒你不要把已經正確的日常寫法當錯誤；要先看真正的句意，而不是只背一條「更正式」的偏好。"},{"title":"針對這句的錯法或疑問","body":"即使沒有逗號，who later ... 也可交代此人的後來經歷。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：She married a man who later became a mayor. ✓。你可以先把句中介紹的部分拿走，再放回來；即使沒有逗號，who later ... 也可交代此人的後來經歷。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是文法真的不成立，還是只是比較少見／比較正式？只有真正錯誤才打 ✗。"}]'::jsonb),
  (284, '[{"title":"把句子讀明白","body":"逗號之前先說完「My older sister」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"句中補充子句有前後兩個逗號。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：My father, who lives in Tai Po is coming home. → My father, who lives in Tai Po, is coming home.。因為句中補充關係子句需要兩邊逗號。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (285, '[{"title":"把句子讀明白","body":"把每一組介紹讀清楚，先問「前面的這個名詞正在做甚麼／被人做了甚麼？」；不要把別人的動詞或主句的動詞算到它身上。"},{"title":"針對這句的錯法或疑問","body":"找出 are 自己對應哪個主語。真正主句主語 woman 單數。 is 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The man who owns the shop that sells cakes is here.。who 對 man，that 對 shop，各有自己的主語。看它怎樣處理「are → is」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：兩個 who／that 是否分別指不同名詞？它們後面的動詞有沒有跟錯人或物？"}]'::jsonb),
  (286, '[{"title":"把句子讀明白","body":"找 to 後面的動詞和真正做事的人：是 first runner 自己 arrive，還是有人要 sign forms？"},{"title":"針對這句的錯法或疑問","body":"driver 是駕車者，him 是被送的人；意思必須清楚。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：Ben needs a driver to take him home. ✓。你可以先把句中介紹的部分拿走，再放回來；driver 是駕車者，him 是被送的人；意思必須清楚。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：to 後動詞是否原形？要講 sit on a chair 時，那個 on 有沒有跟着保留？"}]'::jsonb),
  (287, '[{"title":"把句子讀明白","body":"這題專門提醒你不要把已經正確的日常寫法當錯誤；要先看真正的句意，而不是只背一條「更正式」的偏好。"},{"title":"針對這句的錯法或疑問","body":"關係子句把介詞放前面時，指物通常用 in which／on which／with which，不能直接用 in that 代替。但 the room that we met in 可以，因為介詞放在最後。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：This is the friend I was speaking to.。介詞 to 放句尾完全可以合乎標準英文。看它怎樣處理「that → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是文法真的不成立，還是只是比較少見／比較正式？只有真正錯誤才打 ✗。"}]'::jsonb),
  (288, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"句中原來的 saw him 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；that 已佔據 saw 的受詞位置；him 重複指同一孩子。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The coat that I bought is warm enough for winter.。that 已代表 coat，bought 後面不再重複 it。看它怎樣處理「saw him → saw」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (289, '[{"title":"把句子讀明白","body":"把短描述還原成 who is doing／which was made／which is being repaired 讀一次，看看誰做、誰被做、動作是否正在發生。"},{"title":"針對這句的錯法或疑問","body":"原句的 carried 在此處不合用；主動拿袋的人用 carrying 介紹。 正確修改是 carried → carrying，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The woman carrying the box is our art teacher.。carrying 的做事者是 woman，不是 box。看它怎樣處理「carried → carrying」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (290, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"在 is responsible 裏，woman 是主語；I think 只是插入語。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The volunteer whom arranged the chairs was thanked. → The volunteer who arranged the chairs was thanked.。因為whom 是受詞用法，不能在此代替做事的主語 who。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (291, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"句中原來的 does she live 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；外面是問句，關係子句不用疑問倒裝。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：Do you know the pupil who lives on the third floor?。主問句用 Do，關係子句 who lives 仍用一般陳述次序。看它怎樣處理「does she live → lives」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (292, '[{"title":"把句子讀明白","body":"把短描述還原成 who is doing／which was made／which is being repaired 讀一次，看看誰做、誰被做、動作是否正在發生。"},{"title":"針對這句的錯法或疑問","body":"找出 needs 自己對應哪個主語。People 複數，主句動詞用 need。 need 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：People working at night often need extra rest.。working at night 可以描述一類人，不一定只是此刻正在做。看它怎樣處理「needs → need」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (293, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"正式前置 from which 和較口語 came from 可相近。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The town from which my grandfather came is small. ✓。你可以先把句中介紹的部分拿走，再放回來；正式前置 from which 和較口語 came from 可相近。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (294, '[{"title":"把句子讀明白","body":"這題專門提醒你不要把已經正確的日常寫法當錯誤；要先看真正的句意，而不是只背一條「更正式」的偏好。"},{"title":"針對這句的錯法或疑問","body":"現代英文一般用 from which 而不用古舊 whence。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：We returned to the village from which our family came. ✓。你可以先把句中介紹的部分拿走，再放回來；現代英文一般用 from which 而不用古舊 whence。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是文法真的不成立，還是只是比較少見／比較正式？只有真正錯誤才打 ✗。"}]'::jsonb),
  (295, '[{"title":"把句子讀明白","body":"把每一組介紹讀清楚，先問「前面的這個名詞正在做甚麼／被人做了甚麼？」；不要把別人的動詞或主句的動詞算到它身上。"},{"title":"針對這句的錯法或疑問","body":"who 對 man，that 對 shop，各有自己的主語。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The woman who owns the bakery that sells bread are here. → The woman who owns the bakery that sells bread is here.。因為真正主句主語 woman 單數。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：兩個 who／that 是否分別指不同名詞？它們後面的動詞有沒有跟錯人或物？"}]'::jsonb),
  (296, '[{"title":"把句子讀明白","body":"把每一組介紹讀清楚，先問「前面的這個名詞正在做甚麼／被人做了甚麼？」；不要把別人的動詞或主句的動詞算到它身上。"},{"title":"針對這句的錯法或疑問","body":"前一層限定女人，後一層 which 補充商店資訊。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The woman who owns the shop, which opened last month, is kind. ✓。你可以先把句中介紹的部分拿走，再放回來；前一層限定女人，後一層 which 補充商店資訊。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：兩個 who／that 是否分別指不同名詞？它們後面的動詞有沒有跟錯人或物？"}]'::jsonb),
  (297, '[{"title":"把句子讀明白","body":"找 to 後面的動詞和真正做事的人：是 first runner 自己 arrive，還是有人要 sign forms？"},{"title":"針對這句的錯法或疑問","body":"to 不定詞後用原形 sign。 這一題只需把 signing 改為 sign；不是把整句所有動詞一起換時態。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：I have several emails to answer before lunch.。to answer 說明哪些電郵需要處理，不一定表示必須。看它怎樣處理「signing → sign」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：to 後動詞是否原形？要講 sit on a chair 時，那個 on 有沒有跟着保留？"}]'::jsonb),
  (298, '[{"title":"把句子讀明白","body":"把每一組介紹讀清楚，先問「前面的這個名詞正在做甚麼／被人做了甚麼？」；不要把別人的動詞或主句的動詞算到它身上。"},{"title":"針對這句的錯法或疑問","body":"找出 open 自己對應哪個主語。shop 是單數，內層用 opens。 opens 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The man who owns the shop that sells cakes is here.。who 對 man，that 對 shop，各有自己的主語。看它怎樣處理「open → opens」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：兩個 who／that 是否分別指不同名詞？它們後面的動詞有沒有跟錯人或物？"}]'::jsonb),
  (299, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"原句的 man works 在此處不合用；做主語的關係字不能直接省略。 正確修改是 man works → man who works，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The dog that barked loudly frightened the visitors.。that 是 barked 的主語，標準書面語須保留。看它怎樣處理「man works → man who works」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (300, '[{"title":"把句子讀明白","body":"逗號之前先說完「My two cousins」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"補充句不把兩位表親再劃成較小的群組。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：My two cousins, who both live abroad, are coming home. ✓。你可以先把句中介紹的部分拿走，再放回來；補充句不把兩位表親再劃成較小的群組。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (301, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"that 是 found 的受詞，the child 才是做事者。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The toy that the child found was hidden under a bench. ✓。你可以先把句中介紹的部分拿走，再放回來；that 是 found 的受詞，the child 才是做事者。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (302, '[{"title":"把句子讀明白","body":"找 to 後面的動詞和真正做事的人：是 first runner 自己 arrive，還是有人要 sign forms？"},{"title":"針對這句的錯法或疑問","body":"place 表示坐的地方；chair 則常說 chair to sit on。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：We need a chair to sit during the talk. → We need a chair to sit on during the talk.。因為chair 是坐在其上的物件，介詞 on 不能漏。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：to 後動詞是否原形？要講 sit on a chair 時，那個 on 有沒有跟着保留？"}]'::jsonb),
  (303, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"部分數量 two of which 指前面的一組物件。 把前面的名詞代入那個關係字的位置，試讀成普通句，就可看出哪個字不合這句的意思。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：She bought four cups, two of which were blue.。two of which 指四隻杯中的兩隻，補充句用 which。看它怎樣處理「that → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (304, '[{"title":"把句子讀明白","body":"先問後面的字是在幫忙指出「哪一個人／哪一件事」，還是在補充已知道的人／物；這會影響逗號及能否用 that。"},{"title":"針對這句的錯法或疑問","body":"原句的 ever see 在此處不合用；到目前為止的最高級經驗可用現在完成式。 正確修改是 ever see → have ever seen，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：This is the best film I have seen this term.。最高級後可用零受詞關係字；不必強迫 that。看它怎樣處理「ever see → have ever seen」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (305, '[{"title":"把句子讀明白","body":"逗號之前先說完「The lift broke down」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"which 可指逗號前整件事：例如「比賽取消」導致球員失望；不是只說某個叫 match 的東西。這類逗號後評論／結果不能直接換成 that。"},{"title":"看同一文法點的對照","body":"原句：The lift broke down, which caused a delay. ✓。你可以先把句中介紹的部分拿走，再放回來；which 指升降機壞掉的整件事，並交代結果。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面是在評論剛剛發生的整件事，還是找哪一個人／物？前者常用逗號 which，不可直接換成 that。"}]'::jsonb),
  (306, '[{"title":"把句子讀明白","body":"把短描述還原成 who is doing／which was made／which is being repaired 讀一次，看看誰做、誰被做、動作是否正在發生。"},{"title":"針對這句的錯法或疑問","body":"過去分詞短語可保留 by 表明設計者。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The picture painted by Sara it won a prize. → The picture painted by Sara won a prize.。因為主句已是 The picture 作主語，不多加 it。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (307, '[{"title":"把句子讀明白","body":"逗號之前先說完「She won the prize」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"which 可指逗號前整件事：例如「比賽取消」導致球員失望；不是只說某個叫 match 的東西。這類逗號後評論／結果不能直接換成 that。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：She won the scholarship, which made her family proud.。指整件事時用 which，不應直接換成 that。看它怎樣處理「was delighted → delighted」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面是在評論剛剛發生的整件事，還是找哪一個人／物？前者常用逗號 which，不可直接換成 that。"}]'::jsonb),
  (308, '[{"title":"把句子讀明白","body":"逗號之前先說完「She remembered my birthday」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"為甚麼那個 that 不能留？ 逗號前已交代清楚對象／整件事，逗號後只是在補充。標準英文不在這類補充關係子句用 that。如果後面是在評論整件事，要用 which；如果只是接着介紹一位已知的人，用 who。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：She remembered my birthday, which was thoughtful.。which 評價她記得生日這件事，而非生日這個日期。看它怎樣處理「that → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面是在評論剛剛發生的整件事，還是找哪一個人／物？前者常用逗號 which，不可直接換成 that。"}]'::jsonb),
  (309, '[{"title":"把句子讀明白","body":"看看 It was ... who/that 是在強調「正是誰」，還是 the news/fact that ... 在說「消息是甚麼」。"},{"title":"針對這句的錯法或疑問","body":"which dress 引出不知道哪件，不是介紹外面的 dress。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：I do not know which dress did she buy. → I do not know which dress she bought.。因為間接問句不倒裝，過去用 bought。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是在強調某個人，還是在說明 the news／the fact 的內容？兩種 that 的工作不同。"}]'::jsonb),
  (310, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"who sits beside the window 是介紹 pupil 的資料，並非另一個獨立主句。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The pupil who sits beside the window won the art prize. ✓。你可以先把句中介紹的部分拿走，再放回來；who sits beside the window 是介紹 pupil 的資料，並非另一個獨立主句。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (311, '[{"title":"把句子讀明白","body":"找 to 後面的動詞和真正做事的人：是 first runner 自己 arrive，還是有人要 sign forms？"},{"title":"針對這句的錯法或疑問","body":"原句的 not be ignored 在此處不合用；否定的待處理用途寫 not to be ignored。 正確修改是 not be ignored → not to be ignored，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：These are instructions not to be ignored.。not to be ignored 保留「不可忽略」的否定。看它怎樣處理「not be ignored → not to be ignored」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：to 後動詞是否原形？要講 sit on a chair 時，那個 on 有沒有跟着保留？"}]'::jsonb),
  (312, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"正式人稱前置介詞配 whom。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The person for who I bought the flowers is my aunt. → The person for whom I bought the flowers is my aunt.。因為正式前置 for 後指人用 whom。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (313, '[{"title":"把句子讀明白","body":"這句有幾個動詞？先分開找每個動詞自己的主語，不要把主句的人數或時間誤套進關係小句。"},{"title":"針對這句的錯法或疑問","body":"do not swim 限定沒有游泳的孩子。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The students who doesn''t swim may stay here. → The students who don''t swim may stay here.。因為students 複數，否定助動詞用 don''t。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個動詞真正的主語是單數還是複數？時間又是在過去、現在或將來？"}]'::jsonb),
  (314, '[{"title":"把句子讀明白","body":"逗號之前先說完「Our cat」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"為甚麼那個 that 不能留？ 逗號前已交代清楚對象／整件事，逗號後只是在補充。標準英文不在這類補充關係子句用 that。如果後面是在評論整件事，要用 which；如果只是接着介紹一位已知的人，用 who。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：Our dog, who enjoys attention, waited by the gate.。把熟悉寵物當作有個性的成員時 who 可以成立。看它怎樣處理「that → who」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (315, '[{"title":"把句子讀明白","body":"把短描述還原成 who is doing／which was made／which is being repaired 讀一次，看看誰做、誰被做、動作是否正在發生。"},{"title":"針對這句的錯法或疑問","body":"句中原來的 it won 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；主句已是 The picture 作主語，不多加 it。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The poster designed by our class won first prize.。過去分詞短語可保留 by 表明設計者。看它怎樣處理「it won → won」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (316, '[{"title":"把句子讀明白","body":"看看 It was ... who/that 是在強調「正是誰」，還是 the news/fact that ... 在說「消息是甚麼」。"},{"title":"針對這句的錯法或疑問","body":"whom 通常不是做事的主語。這裏是「那個人安排／唱歌／知道答案」，即 who arranged／who sings／who is ...；I think 只是中間的說話者看法，不會把 who 變成受詞。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：It was May who found the missing key.。It was ... who 特別強調動作由 May 做。看它怎樣處理「whom → who」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是在強調某個人，還是在說明 the news／the fact 的內容？兩種 that 的工作不同。"}]'::jsonb),
  (317, '[{"title":"把句子讀明白","body":"找 to 後面的動詞和真正做事的人：是 first runner 自己 arrive，還是有人要 sign forms？"},{"title":"針對這句的錯法或疑問","body":"to be signed 是待人簽署的被動形式。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：These documents are to be signing today. → These documents are to be signed today.。因為被動 to be + 過去分詞 signed。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：to 後動詞是否原形？要講 sit on a chair 時，那個 on 有沒有跟着保留？"}]'::jsonb),
  (318, '[{"title":"把句子讀明白","body":"逗號之前先說完「Mia sent a photo」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"which 可指逗號前整件事：例如「比賽取消」導致球員失望；不是只說某個叫 match 的東西。這類逗號後評論／結果不能直接換成 that。"},{"title":"看同一文法點的對照","body":"原句：Mia sent a photo, which was slightly blurry. ✓。你可以先把句中介紹的部分拿走，再放回來；was blurry 描述 photo 本身，逗號不代表一定指整句。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面是在評論剛剛發生的整件事，還是找哪一個人／物？前者常用逗號 which，不可直接換成 that。"}]'::jsonb),
  (319, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"句中原來的 which it 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；which 已是 was created 的被動主語。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The clock which stopped at noon needs repairing.。which 是 stopped 的主語，不是人在做事。看它怎樣處理「which it → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (320, '[{"title":"把句子讀明白","body":"把短描述還原成 who is doing／which was made／which is being repaired 讀一次，看看誰做、誰被做、動作是否正在發生。"},{"title":"針對這句的錯法或疑問","body":"carrying 的做事者是 woman，不是 box。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The woman carried a bag is our teacher. → The woman carrying a bag is our teacher.。因為主動拿袋的人用 carrying 介紹。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (321, '[{"title":"把句子讀明白","body":"原句想說「在外面玩的孩子現在累了」。需要一小段描述來說明是哪批孩子。"},{"title":"針對這句的錯法或疑問","body":"played 是完整過去式動詞，不可以直接擠在 The children ... are tired 中間。這裏用 playing outside 描述自己在外面玩的孩子；也可改成完整的 who were playing outside。"},{"title":"看同一文法點的對照","body":"The children playing outside are now tired. ✓；The children played outside. They are now tired. ✓（拆成兩句、兩個已完成的動作。）"},{"title":"下次遇到這種題怎樣自己判斷","body":"先辨認 playing 是名詞後面的描述；played 若要作主動詞，就要另組完整句或改成 who played。"}]'::jsonb),
  (322, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"place 後適當地點關係可以零形式。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：This is the place we used to play chess. ✓。你可以先把句中介紹的部分拿走，再放回來；place 後適當地點關係可以零形式。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (323, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"音樂家是人，數量部分後用 whom。 把前面的名詞代入那個關係字的位置，試讀成普通句，就可看出哪個字不合這句的意思。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：Ten guests attended, three of whom stayed late.。three of whom 指十位客人中的三位。看它怎樣處理「which → whom」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (324, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"句中原來的 who he 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；who 已代表 boy 並作 lives 的主語。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The girl who helped me works in the office.。who 已是 helped 的主語，毋須另寫 she。看它怎樣處理「who he → who」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (325, '[{"title":"把句子讀明白","body":"先問後面的字是在幫忙指出「哪一個人／哪一件事」，還是在補充已知道的人／物；這會影響逗號及能否用 that。"},{"title":"針對這句的錯法或疑問","body":"that has a yellow cover 是必要辨識資料，通常不用逗號隔開。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The pupils who missed the bus, must report to the office. → The pupils who missed the bus must report to the office.。因為限定主語與主要動詞之間不應多插一個逗號。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (326, '[{"title":"把句子讀明白","body":"把每一組介紹讀清楚，先問「前面的這個名詞正在做甚麼／被人做了甚麼？」；不要把別人的動詞或主句的動詞算到它身上。"},{"title":"針對這句的錯法或疑問","body":"找出 play 自己對應哪個主語。最內層 that 回指 student 單數。 plays 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The man who owns the shop that sells cakes is here.。who 對 man，that 對 shop，各有自己的主語。看它怎樣處理「play → plays」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：兩個 who／that 是否分別指不同名詞？它們後面的動詞有沒有跟錯人或物？"}]'::jsonb),
  (327, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"句中原來的 which it 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；which 已是 shows 的主語，it 重複了同一物件。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The printer which broke yesterday needs a new cable.。which 指 printer；這部打印機是 broke 的主語。看它怎樣處理「which it → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (328, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"where 表示動作在公園發生。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：This is the café which we meet after class. → This is the café where we meet after class.。因為meet 表示在咖啡店見面，需地點關係 where 或 in which。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (329, '[{"title":"把句子讀明白","body":"找 to 後面的動詞和真正做事的人：是 first runner 自己 arrive，還是有人要 sign forms？"},{"title":"針對這句的錯法或疑問","body":"work to do 是自然名詞修飾語，不必硬說每次省略了 who。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：We have plenty of work to do before the show. ✓。你可以先把句中介紹的部分拿走，再放回來；work to do 是自然名詞修飾語，不必硬說每次省略了 who。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：to 後動詞是否原形？要講 sit on a chair 時，那個 on 有沒有跟着保留？"}]'::jsonb),
  (330, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"句中原來的 know her 含有不該重複的代名詞。前面的名詞／關係字已代表同一個人或物；關係字已指 singer，裏層動詞不再多加 her。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The student who I think knows the answer raised a hand.。在 knows the answer 一層，student 是主語，因此 who 正確。看它怎樣處理「know her → know」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (331, '[{"title":"把句子讀明白","body":"先把插入的補充拿掉：The bridge needs repairs／The folder is locked。再把補充放回去：the surface／contents of which 是「橋面／文件夾內容」，不是整條橋／整個文件夾在做動作。"},{"title":"針對這句的錯法或疑問","body":"of which 沒有錯。 它相當於 whose surface / whose contents，意思是「那個物件的表面／內容」。這兩種都合乎現代標準英文；不應只因 of which 較正式而打 ✗。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The folder, whose contents is private, is locked. → The folder, whose contents are private, is locked.。因為contents 為複數，用 are。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面的名詞是誰的？如果試用 who’s，展開成 who is／who has 還能讀通嗎？"}]'::jsonb),
  (332, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"whom 通常不是做事的主語。這裏是「那個人安排／唱歌／知道答案」，即 who arranged／who sings／who is ...；I think 只是中間的說話者看法，不會把 who 變成受詞。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The dog that barked loudly frightened the visitors.。that 是 barked 的主語，標準書面語須保留。看它怎樣處理「whom → who」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (333, '[{"title":"把句子讀明白","body":"找 to 後面的動詞和真正做事的人：是 first runner 自己 arrive，還是有人要 sign forms？"},{"title":"針對這句的錯法或疑問","body":"原句的 sit 在此處不合用；chair 是坐在其上的物件，介詞 on 不能漏。 正確修改是 sit → sit on，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：We need a place to sit during the break.。place 表示坐的地方；chair 則常說 chair to sit on。看它怎樣處理「sit → sit on」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：to 後動詞是否原形？要講 sit on a chair 時，那個 on 有沒有跟着保留？"}]'::jsonb),
  (334, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"省去受詞 that 後仍有 my brother 作 chose 的主語。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The song my brother chose was beautiful. ✓。你可以先把句中介紹的部分拿走，再放回來；省去受詞 that 後仍有 my brother 作 chose 的主語。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (335, '[{"title":"把句子讀明白","body":"把每一組介紹讀清楚，先問「前面的這個名詞正在做甚麼／被人做了甚麼？」；不要把別人的動詞或主句的動詞算到它身上。"},{"title":"針對這句的錯法或疑問","body":"明說 who 介紹 woman，可避免把網球活動誤配給 daughter。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：I met a woman who plays tennis and has a daughter. ✓。你可以先把句中介紹的部分拿走，再放回來；明說 who 介紹 woman，可避免把網球活動誤配給 daughter。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：兩個 who／that 是否分別指不同名詞？它們後面的動詞有沒有跟錯人或物？"}]'::jsonb),
  (336, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"I 是 called 的主語，who 是被致電的男孩；受詞 who 在現代英文可以用。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The boy who I called yesterday has replied. ✓。你可以先把句中介紹的部分拿走，再放回來；I 是 called 的主語，who 是被致電的男孩；受詞 who 在現代英文可以用。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (337, '[{"title":"把句子讀明白","body":"把短描述還原成 who is doing／which was made／which is being repaired 讀一次，看看誰做、誰被做、動作是否正在發生。"},{"title":"針對這句的錯法或疑問","body":"主動進行的 children 可用 playing 介紹。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The teacher siting by the door is our librarian. → The teacher sitting by the door is our librarian.。因為sit 的 -ing 拼作 sitting。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (338, '[{"title":"把句子讀明白","body":"看看 It was ... who/that 是在強調「正是誰」，還是 the news/fact that ... 在說「消息是甚麼」。"},{"title":"針對這句的錯法或疑問","body":"With + 名詞 + -ing 交代背景，不等同一般 who 子句。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：With the children playing outside, the house was quiet. ✓。你可以先把句中介紹的部分拿走，再放回來；With + 名詞 + -ing 交代背景，不等同一般 who 子句。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是在強調某個人，還是在說明 the news／the fact 的內容？兩種 that 的工作不同。"}]'::jsonb),
  (339, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"句首 Whatever happens 是「無論發生甚麼」的讓步子句。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：Whatever happens, you remains calm. → Whatever happens, you remain calm.。因為you 作主語，動詞原形；Whatever happens 本身正確。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (340, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"正式可把 in 放在 which 前。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The room in that we met is now locked. → The room in which we met is now locked.。因為in 是前置介詞，後用 which。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (341, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"為甚麼這裏要 whom？ 介詞（to／for／with）已放在關係字前面；在標準正式用法中，人物要寫 to whom／for whom／with whom。但 the person who I spoke to 也正確，因為介詞放在句尾，結構不同。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The tutor to whom I sent the email replied promptly.。to 是前置介詞，指人時正式寫 whom。看它怎樣處理「who → whom」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (342, '[{"title":"把句子讀明白","body":"這句有幾個動詞？先分開找每個動詞自己的主語，不要把主句的人數或時間誤套進關係小句。"},{"title":"針對這句的錯法或疑問","body":"找出 lives 自己對應哪個主語。girls 複數，who 子句用 live。 live 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The boys who live upstairs are friendly.。boys 是複數，關係子句用 live 而不是 lives。看它怎樣處理「lives → live」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個動詞真正的主語是單數還是複數？時間又是在過去、現在或將來？"}]'::jsonb),
  (343, '[{"title":"把句子讀明白","body":"這句有幾個動詞？先分開找每個動詞自己的主語，不要把主句的人數或時間誤套進關係小句。"},{"title":"針對這句的錯法或疑問","body":"找出 applies 自己對應哪個主語。all who 指多人，全組用 apply。 apply 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：All who applied received a reply.。All who ... 可以指符合條件的全體申請人。看它怎樣處理「applies → apply」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個動詞真正的主語是單數還是複數？時間又是在過去、現在或將來？"}]'::jsonb),
  (344, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"point 是抽象階段，不是真正地圖地點。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：We reached a point when we needed to decide. → We reached a point where we needed to decide.。因為point 指抽象情況，常配 where。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (345, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"表示時間的限定子句有時可省 when。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：I will never forget the morning we met. ✓。你可以先把句中介紹的部分拿走，再放回來；表示時間的限定子句有時可省 when。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (346, '[{"title":"把句子讀明白","body":"找 to 後面的動詞和真正做事的人：是 first runner 自己 arrive，還是有人要 sign forms？"},{"title":"針對這句的錯法或疑問","body":"next person to speak 表示輪到她發言。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The next person to speaks is our monitor. → The next person to speak is our monitor.。因為to 後主動詞保持原形。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：to 後動詞是否原形？要講 sit on a chair 時，那個 on 有沒有跟着保留？"}]'::jsonb),
  (347, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"whomever 是 trust 的受詞，屬較正式寫法。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：Invite whoever you trusts to the event. → Invite whoever you trust to the event.。因為you 是 trust 的主語，動詞不加 -s。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (348, '[{"title":"把句子讀明白","body":"這題專門提醒你不要把已經正確的日常寫法當錯誤；要先看真正的句意，而不是只背一條「更正式」的偏好。"},{"title":"針對這句的錯法或疑問","body":"who’s = who is 或 who has，不能表「某人的」。這句後面跟母親／單車／設計，所以必須寫 whose。試展開 who’s 就會知道原句讀不通。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：We discussed a policy whose effects were unclear.。whose 可介紹政策等抽象事物的所屬關係。看它怎樣處理「who''s → whose」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是文法真的不成立，還是只是比較少見／比較正式？只有真正錯誤才打 ✗。"}]'::jsonb),
  (349, '[{"title":"把句子讀明白","body":"先問後面的字是在幫忙指出「哪一個人／哪一件事」，還是在補充已知道的人／物；這會影響逗號及能否用 that。"},{"title":"針對這句的錯法或疑問","body":"原句的 bus, must 在此處不合用；限定主語與主要動詞之間不應多插一個逗號。 正確修改是 bus, must → bus must，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The workbook that has a yellow cover belongs to Lily.。that has a yellow cover 是必要辨識資料，通常不用逗號隔開。看它怎樣處理「bus, must → bus must」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (350, '[{"title":"把句子讀明白","body":"逗號之前先說完「The committee」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"把委員會看成其中成員時，who 可用於團體。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The committee, who were smiling, thanked the volunteers. ✓。你可以先把句中介紹的部分拿走，再放回來；把委員會看成其中成員時，who 可用於團體。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (351, '[{"title":"把句子讀明白","body":"這句有幾個動詞？先分開找每個動詞自己的主語，不要把主句的人數或時間誤套進關係小句。"},{"title":"針對這句的錯法或疑問","body":"did not meet 否定見面，不是否定那人打電話。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：I did not meet the person who called me yesterday him. → I did not meet the person who called me yesterday.。因為who 已是 called 的主語；him 在此既無適當位置也無所需受詞。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個動詞真正的主語是單數還是複數？時間又是在過去、現在或將來？"}]'::jsonb),
  (352, '[{"title":"把句子讀明白","body":"把短描述還原成 who is doing／which was made／which is being repaired 讀一次，看看誰做、誰被做、動作是否正在發生。"},{"title":"針對這句的錯法或疑問","body":"not wearing 保留「沒有佩戴」的限制。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The pupils not wears badges must wait outside. → The pupils not wearing badges must wait outside.。因為縮短的否定分詞片語用 not wearing。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (353, '[{"title":"把句子讀明白","body":"找 to 後面的動詞和真正做事的人：是 first runner 自己 arrive，還是有人要 sign forms？"},{"title":"針對這句的錯法或疑問","body":"talk to someone 需要保留句末的 to。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：I need someone whom to talk to about the problem. → I need someone to talk to about the problem.。因為名詞後的 to + 動詞結構不用在 to 前額外加入 whom。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：to 後動詞是否原形？要講 sit on a chair 時，那個 on 有沒有跟着保留？"}]'::jsonb),
  (354, '[{"title":"把句子讀明白","body":"這句有幾個動詞？先分開找每個動詞自己的主語，不要把主句的人數或時間誤套進關係小句。"},{"title":"針對這句的錯法或疑問","body":"在此語境 that 指 box，所以用 is；toys 不是主語。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The box of toys that is under the desk is heavy. ✓。你可以先把句中介紹的部分拿走，再放回來；在此語境 that 指 box，所以用 is；toys 不是主語。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個動詞真正的主語是單數還是複數？時間又是在過去、現在或將來？"}]'::jsonb),
  (355, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"這裏已有前面的名詞（例如 novel／book／all），後面的字只需接回它。what 常相當於「所……的東西」，不能在這種位置再塞進去；用 that，或在合適的受詞位置直接省略。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：What we need is a short break.。what 已包含「需要的事情」，不再加 the thing。看它怎樣處理「what → that」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (356, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"that 連回 leader，補足 become 後面的身分描述。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：She became the leader that I hoped she would become. ✓。你可以先把句中介紹的部分拿走，再放回來；that 連回 leader，補足 become 後面的身分描述。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (357, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"為甚麼這裏要 whom？ 介詞（to／for／with）已放在關係字前面；在標準正式用法中，人物要寫 to whom／for whom／with whom。但 the person who I spoke to 也正確，因為介詞放在句尾，結構不同。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The artist with whom I worked is from Glasgow.。正式人稱前置介詞配 whom。看它怎樣處理「who → whom」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (358, '[{"title":"把句子讀明白","body":"這題專門提醒你不要把已經正確的日常寫法當錯誤；要先看真正的句意，而不是只背一條「更正式」的偏好。"},{"title":"針對這句的錯法或疑問","body":"whose 可介紹政策等抽象事物的所屬關係。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The policy who''s effects were unclear was withdrawn. → The policy whose effects were unclear was withdrawn.。因為政策的效果用 whose，who''s 是 who is/has。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是文法真的不成立，還是只是比較少見／比較正式？只有真正錯誤才打 ✗。"}]'::jsonb),
  (359, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"原句的 how 在此處不合用；the way that ... 或 the way ...，不機械疊加 how。 正確修改是 how → that，其他部分不用改。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：I like the way our coach explains the rules.。the way 後可直接接解釋方法的子句。看它怎樣處理「how → that」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (360, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"標準書面英語的主語 who 必須保留，某些方言省略另當別論。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：There is a visitor who wants to speak to the manager. ✓。你可以先把句中介紹的部分拿走，再放回來；標準書面英語的主語 who 必須保留，某些方言省略另當別論。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (361, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"不加逗號的 who registered early 用來劃出學生中的指定組別。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The students who registered early received their badges. ✓。你可以先把句中介紹的部分拿走，再放回來；不加逗號的 who registered early 用來劃出學生中的指定組別。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (362, '[{"title":"把句子讀明白","body":"先問後面的字是在幫忙指出「哪一個人／哪一件事」，還是在補充已知道的人／物；這會影響逗號及能否用 that。"},{"title":"針對這句的錯法或疑問","body":"找出 finish 自己對應哪個主語。every student 的關係子句動詞用單數。 finishes 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：Anyone who finishes early may leave quietly.。anyone 後面的 who finishes 提出條件，finishes 用單數。看它怎樣處理「finish → finishes」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (363, '[{"title":"把句子讀明白","body":"逗號之前先說完「Ben called Amy」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"who then told 說明 Amy 接着做了甚麼。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：Ben spoke to Amy, which then informed the teacher. → Ben spoke to Amy, who then informed the teacher.。因為Amy 是接着通知老師的人，用 who。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面是在評論剛剛發生的整件事，還是找哪一個人／物？前者常用逗號 which，不可直接換成 that。"}]'::jsonb),
  (364, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"在 knows the answer 一層，student 是主語，因此 who 正確。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The player I think he scored the goal is outside. → The player who I think scored the goal is outside.。因為需要 who 連回 player，who 作 scored 的主語。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (365, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"a parent 雖跟在 to 後面，who runs 仍然修飾 parent。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：I spoke to a parent who runs the chess club. ✓。你可以先把句中介紹的部分拿走，再放回來；a parent 雖跟在 to 後面，who runs 仍然修飾 parent。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (366, '[{"title":"把句子讀明白","body":"先找到 whose 後面的名詞：誰的子女／哪個物件的部分？再找它是單數還是複數。"},{"title":"針對這句的錯法或疑問","body":"找出 are 自己對應哪個主語。whose daughter 是單數主語。 is 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The girl whose parents work here is cheerful.。parents 是複數，關係子句用 work。看它怎樣處理「are → is」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面的名詞是誰的？如果試用 who’s，展開成 who is／who has 還能讀通嗎？"}]'::jsonb),
  (367, '[{"title":"把句子讀明白","body":"這句有幾個動詞？先分開找每個動詞自己的主語，不要把主句的人數或時間誤套進關係小句。"},{"title":"針對這句的錯法或疑問","body":"must 在關係子句仍表義務，不能改成 may。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The students who must to attend have received an email. → The students who must attend have received an email.。因為modal must 後不加 to。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個動詞真正的主語是單數還是複數？時間又是在過去、現在或將來？"}]'::jsonb),
  (368, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"whom 指收文件的人；folder 是另一個受詞。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：The student whom I gave the folder to thanked me. ✓。你可以先把句中介紹的部分拿走，再放回來；whom 指收文件的人；folder 是另一個受詞。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (369, '[{"title":"把句子讀明白","body":"找 to 後面的動詞和真正做事的人：是 first runner 自己 arrive，還是有人要 sign forms？"},{"title":"針對這句的錯法或疑問","body":"first student to arrive 強調抵達次序。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：She was the first visitor to arrived at the museum. → She was the first visitor to arrive at the museum.。因為first visitor to 後接原形 arrive。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：to 後動詞是否原形？要講 sit on a chair 時，那個 on 有沒有跟着保留？"}]'::jsonb),
  (370, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"正式前置 for 後面用 whom，不用 who。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：That was the colleague with who I worked last summer. → That was the colleague with whom I worked last summer.。因為with 放前面且指人，用 whom。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (371, '[{"title":"把句子讀明白","body":"先問後面的字是在幫忙指出「哪一個人／哪一件事」，還是在補充已知道的人／物；這會影響逗號及能否用 that。"},{"title":"針對這句的錯法或疑問","body":"who need extra help 限定學生的範圍。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：Students who need extra help may stay after class. ✓。你可以先把句中介紹的部分拿走，再放回來；who need extra help 限定學生的範圍。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (372, '[{"title":"把句子讀明白","body":"把每一組介紹讀清楚，先問「前面的這個名詞正在做甚麼／被人做了甚麼？」；不要把別人的動詞或主句的動詞算到它身上。"},{"title":"針對這句的錯法或疑問","body":"已持續到當時的等候用 had been + -ing。 這一題只需把 had been wait 改為 had been waiting；不是把整句所有動詞一起換時態。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The boy who had been waiting for an hour finally left.。完整子句保留等候時長及時間關係，比強縮更清楚。看它怎樣處理「had been wait → had been waiting」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：人是做事者（-ing），還是物件被做（made／repaired）？short form 有沒有丟失 not 或時間資訊？"}]'::jsonb),
  (373, '[{"title":"把句子讀明白","body":"這句有幾個動詞？先分開找每個動詞自己的主語，不要把主句的人數或時間誤套進關係小句。"},{"title":"針對這句的錯法或疑問","body":"modal must 後不加 to。 這一題只需把 must to attend 改為 must attend；不是把整句所有動詞一起換時態。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The students who must attend will receive an email.。must 在關係子句仍表義務，不能改成 may。看它怎樣處理「must to attend → must attend」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個動詞真正的主語是單數還是複數？時間又是在過去、現在或將來？"}]'::jsonb),
  (374, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"省去受詞關係字後，speak to 的介詞仍在。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The student to I spoke smiled. → The student to whom I spoke smiled.。因為前置介詞後不能直接省去關係字；也可改成 I spoke to。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (375, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"who 取代原本第二句的 she/he，合句時不再重複主語。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The man that he helped our group is a volunteer. → The man that helped our group is a volunteer.。因為that 已是 helped 的主語，不再重複 he。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (376, '[{"title":"把句子讀明白","body":"先問後面的字是在幫忙指出「哪一個人／哪一件事」，還是在補充已知道的人／物；這會影響逗號及能否用 that。"},{"title":"針對這句的錯法或疑問","body":"找出 are 自己對應哪個主語。someone 單數，存在句用 there is。 is 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：There is somebody who wants to join the choir.。there is 用來介紹新人物，who wants 再提供資料。看它怎樣處理「are → is」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (377, '[{"title":"把句子讀明白","body":"這句有幾個動詞？先分開找每個動詞自己的主語，不要把主句的人數或時間誤套進關係小句。"},{"title":"針對這句的錯法或疑問","body":"找出 works 自己對應哪個主語。whose parents 複數，動詞用 work。 work 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：All who applied received a reply.。All who ... 可以指符合條件的全體申請人。看它怎樣處理「works → work」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個動詞真正的主語是單數還是複數？時間又是在過去、現在或將來？"}]'::jsonb),
  (378, '[{"title":"把句子讀明白","body":"這句有幾個動詞？先分開找每個動詞自己的主語，不要把主句的人數或時間誤套進關係小句。"},{"title":"針對這句的錯法或疑問","body":"找出 doesn''t 自己對應哪個主語。students 複數，否定助動詞用 don''t。 don''t 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The children who do not swim can stay near the benches.。do not swim 限定沒有游泳的孩子。看它怎樣處理「doesn''t → don''t」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個動詞真正的主語是單數還是複數？時間又是在過去、現在或將來？"}]'::jsonb),
  (379, '[{"title":"把句子讀明白","body":"先把關係字換回前面的名詞，再把「who／which／that」之後讀成小句：誰做動作？誰被做了動作？"},{"title":"針對這句的錯法或疑問","body":"本句介紹的是人，而後面的動詞也是這個人在做，所以用 who。which 常介紹物件；但若是人物後面的普通限定句，that 有時也可用。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The nurse who checked the students was very patient.。who 指護士，而護士就是 checked 的人。看它怎樣處理「which → who」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (380, '[{"title":"把句子讀明白","body":"先找到 whose 後面的名詞：誰的子女／哪個物件的部分？再找它是單數還是複數。"},{"title":"針對這句的錯法或疑問","body":"parents 是複數，關係子句用 work。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The girl whose brother are a pilot smiled. → The girl whose brother is a pilot smiled.。因為brother 單數，用 is。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面的名詞是誰的？如果試用 who’s，展開成 who is／who has 還能讀通嗎？"}]'::jsonb),
  (381, '[{"title":"把句子讀明白","body":"把 news／fact 後面當作「消息／事實的內容」讀一次：例如 the school will close 是一整件事，並不是一個欠了受詞的動作。"},{"title":"針對這句的錯法或疑問","body":"fact 後說明完整事實內容用 that。 把前面的名詞代入那個關係字的位置，試讀成普通句，就可看出哪個字不合這句的意思。"},{"title":"看同一文法點的對照","body":"The fact that she left surprised us. ✓（說明事實）；The fact which she mentioned surprised us. ✓（事實是 mentioned 的受詞）。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是在強調某個人，還是在說明 the news／the fact 的內容？兩種 that 的工作不同。"}]'::jsonb),
  (382, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"最高級後可用零受詞關係字；不必強迫 that。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：These are the best photographs that I ever see. → These are the best photographs that I have ever seen.。因為到目前為止的最高級經驗可用現在完成式。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (383, '[{"title":"把句子讀明白","body":"逗號之前先說完「Mia」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"Mia 已指出身份，逗號內是補充消息。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：Mia, who lives near the school, is joining us. ✓。你可以先把句中介紹的部分拿走，再放回來；Mia 已指出身份，逗號內是補充消息。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (384, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"when 介紹事情發生的時間。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：I remember the day where we first met. → I remember the day when we first met.。因為day 是時間，普通寫法用 when。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (385, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"the afternoon 後面的時間關係可省 when。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：I remember the afternoon we first met. ✓。你可以先把句中介紹的部分拿走，再放回來；the afternoon 後面的時間關係可省 when。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個 who／which／that 在小句中是做動作的，還是被做動作的？關係字已代替的名詞，是否又被寫多一次？"}]'::jsonb),
  (386, '[{"title":"把句子讀明白","body":"逗號之前先說完「They finished early」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"本句介紹的是物件／活動而不是人，所以用 which。你不能只因為那件東西「做了某件事」（例如時鐘停了），就把它當成人用 who。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：They shared the work and finished early, which pleased the teacher.。which 可回指前面幾件一起發生的事情。看它怎樣處理「who → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面是在評論剛剛發生的整件事，還是找哪一個人／物？前者常用逗號 which，不可直接換成 that。"}]'::jsonb),
  (387, '[{"title":"把句子讀明白","body":"逗號之前先說完「He missed the last bus」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"which 評論錯過巴士整件事，而不一定指巴士本身。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：Ben missed the bus, that annoyed him. → Ben missed the bus, which annoyed him.。因為回指整件錯過巴士的事，用 which。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (388, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"whoever 表符合條件的任何人，finishes 用單數。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：Whoever finish first may go home. → Whoever finishes first may go home.。因為whoever 作主語，一般動詞用單數 finishes。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (389, '[{"title":"把句子讀明白","body":"逗號之前先說完「They shared the work and finished early」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"which 可指逗號前整件事：例如「比賽取消」導致球員失望；不是只說某個叫 match 的東西。這類逗號後評論／結果不能直接換成 that。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：They finished early, who pleased the teacher. → They finished early, which pleased the teacher.。因為整個完成提早這件事是 which 的對象。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面是在評論剛剛發生的整件事，還是找哪一個人／物？前者常用逗號 which，不可直接換成 that。"}]'::jsonb),
  (390, '[{"title":"把句子讀明白","body":"試把中間的介紹遮住，再讀一遍主要句子，看看前面的名詞和後面的動詞怎樣對應。"},{"title":"針對這句的錯法或疑問","body":"最高級搭 ever 可說到目前為止的經驗。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：These are the best songs that I have ever hearing. → These are the best songs that I have ever heard.。因為have 後配過去分詞 heard；ever 可與最高級經驗並用。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這個動詞真正的主語是單數還是複數？時間又是在過去、現在或將來？"}]'::jsonb),
  (391, '[{"title":"把句子讀明白","body":"先找到 whose 後面的名詞：誰的子女／哪個物件的部分？再找它是單數還是複數。"},{"title":"針對這句的錯法或疑問","body":"who’s = who is 或 who has，不能表「某人的」。這句後面跟母親／單車／設計，所以必須寫 whose。試展開 who’s 就會知道原句讀不通。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：I met a boy whose mother works in the library.。whose 表示「屬於誰」，不是 who''s (= who is/has)。看它怎樣處理「who''s → whose」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面的名詞是誰的？如果試用 who’s，展開成 who is／who has 還能讀通嗎？"}]'::jsonb),
  (392, '[{"title":"把句子讀明白","body":"逗號之前先說完「The assembly ended early」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"為甚麼那個 that 不能留？ 逗號前已交代清楚對象／整件事，逗號後只是在補充。標準英文不在這類補充關係子句用 that。如果後面是在評論整件事，要用 which；如果只是接着介紹一位已知的人，用 who。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The class was cancelled, which was disappointing.。which 帶出作者對整件事的感受。看它怎樣處理「that → which」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：後面是在評論剛剛發生的整件事，還是找哪一個人／物？前者常用逗號 which，不可直接換成 that。"}]'::jsonb),
  (393, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"where = 在哪裏；when = 在甚麼時候。 這題前面的 day／morning／July 是時間，不是地點，故用 when。the day we met 省略 when 有時也對。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The time when the concert begins has changed.。when 要與前面的 time 和發生時間相配。看它怎樣處理「where → when」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (394, '[{"title":"把句子讀明白","body":"把 news／fact 後面當作「消息／事實的內容」讀一次：例如 the school will close 是一整件事，並不是一個欠了受詞的動作。"},{"title":"針對這句的錯法或疑問","body":"that 套入 fact 說明事實內容，不一定是關係代名詞。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：The fact which she left early surprised us. → The fact that she left early surprised us.。因為fact 後說明完整事實內容用 that。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：是在強調某個人，還是在說明 the news／the fact 的內容？兩種 that 的工作不同。"}]'::jsonb),
  (395, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"visit 直接以 city 作受詞，故用 that 而非 where。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"同一個規則下，這個寫法才需要改：This is the museum where we visited last week. → This is the museum that we visited last week.。因為visit 直接接 museum 作受詞，用 that/which。本題原句沒有犯這個錯。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb),
  (396, '[{"title":"把句子讀明白","body":"把 what／whoever／whatever 整組讀成「……的東西／……的人」，不要自動在前後插另一個相同的代字。"},{"title":"針對這句的錯法或疑問","body":"找出 finish 自己對應哪個主語。whoever 作主語，一般動詞用單數 finishes。 finishes 才和那個主語相配。前面的整句可能仍用另一個時態或單複數，無需一律統一。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：Whoever finishes first may leave the hall.。whoever 表符合條件的任何人，finishes 用單數。看它怎樣處理「finish → finishes」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：句中已有名詞需要被介紹嗎？若是，考慮 that／which；若整組字已表示「任何東西／人」，就不用另加 that。"}]'::jsonb),
  (397, '[{"title":"把句子讀明白","body":"逗號之前先說完「Our aunt」。後面是在加上這件事的影響，還是在給一位已知的人／物增加消息？先看 which／who 究竟指甚麼。"},{"title":"針對這句的錯法或疑問","body":"補充關係子句可交代背景，但不一定明言因果。 這句並沒有犯以上錯誤；若存在另一個更正式或更短的寫法，那只是另一種選擇，並不是原句錯。"},{"title":"看同一文法點的對照","body":"原句：Our aunt, who was feeling ill, left the party early. ✓。你可以先把句中介紹的部分拿走，再放回來；補充關係子句可交代背景，但不一定明言因果。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這一段是在挑出其中一部分，還是給已知對象加補充？逗號會不會改變指的人數？"}]'::jsonb),
  (398, '[{"title":"把句子讀明白","body":"先還原成普通說法：「I spoke to the friend」「I sat on the chair」「I talked about the subject」。介詞是否仍有作用，要看動詞原本怎樣接人或物。"},{"title":"針對這句的錯法或疑問","body":"為甚麼這裏要 whom？ 介詞（to／for／with）已放在關係字前面；在標準正式用法中，人物要寫 to whom／for whom／with whom。但 the person who I spoke to 也正確，因為介詞放在句尾，結構不同。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：The person for whom I bought the gift has arrived.。正式前置 for 後面用 whom，不用 who。看它怎樣處理「who → whom」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：把前面的名詞放回普通句，動詞需要 to／with／in／on／about 哪個介詞？有沒有漏掉？"}]'::jsonb),
  (399, '[{"title":"把句子讀明白","body":"Anyone who finishes early 是「任何一個提早完成的人」。who finishes 加條件：只有提早完成才可以離開。"},{"title":"針對這句的錯法或疑問","body":"雖然 any 讓你想到「好多可能的人」，anyone 作普通主語是單數，所以關係句動詞要用 finishes，不是 finish；may 後卻仍用原形 leave。"},{"title":"看同一文法點的對照","body":"Anyone who finishes early may leave. ✓；Students who finish early may leave. ✓。"},{"title":"下次遇到這種題怎樣自己判斷","body":"用筆畫兩條線：anyone → finishes；may → leave（情態動詞後原形）。"}]'::jsonb),
  (400, '[{"title":"把句子讀明白","body":"看看被介紹的是 day／morning（時間）、park／museum（地方），還是 reason（原因）；另外留意 visit 會直接接「參觀的地方」。"},{"title":"針對這句的錯法或疑問","body":"where = 在哪裏；when = 在甚麼時候。 這題前面的 day／morning／July 是時間，不是地點，故用 when。the day we met 省略 when 有時也對。"},{"title":"看同一文法點的對照","body":"同一文法位置的正確例子：I remember the day when we first performed together.。when 介紹事情發生的時間。看它怎樣處理「where → when」所考的問題。"},{"title":"下次遇到這種題怎樣自己判斷","body":"自問：這裏說的是地點、時間、原因，還是直接參觀某地方？先問這件事，才選 where／when／why／that。"}]'::jsonb)
)
update error_identifier_private.relative_clauses_key as answer_key
set data = jsonb_set(answer_key.data, '{steps}', refreshed.steps, true)
from refreshed
where answer_key.number = refreshed.number;

do $$
begin
  if (select count(*) from error_identifier_private.relative_clauses_key) <> 400
    or exists (
      select 1 from error_identifier_private.relative_clauses_key
      where jsonb_array_length(data -> 'steps') <> 4
    ) then
    raise exception 'Module 4 explanation refresh did not cover all 400 questions';
  end if;
end
$$;
